head.b:skin:
  @media (max-width: 768px) {
    .btn-watch-now {
      display: none !important;
    }
  }

    :root { --bg-main: #000000; --net-red: #000000; --text: #fff; }
    body { background-color:#000000; font-family: 'Roboto', sans-serif; margin: 0; padding: 0; overflow-x: hidden; -webkit-user-select: none; user-select: none; }
    #navbar-iframe { display: none !important; }
    ::-webkit-scrollbar { width: 8px; background: #000000; }
    ::-webkit-scrollbar-thumb { background: #333; border-radius: 4px; }

    .profile-gate { position: fixed; inset: 0; background: #000000; z-index: 9999; display: flex; flex-direction: column; align-items: center; justify-content: center; transition: 0.4s ease-out; }
    .profile-gate.hidden { opacity: 0; pointer-events: none; transform: scale(1.1); }
    .profile-grid { display: flex; gap: 2vw; flex-wrap: wrap; justify-content: center; }
    .profile-item { display: flex; flex-direction: column; align-items: center; cursor: pointer; transition: 0.2s; }
    .profile-item:hover { transform: scale(1.05); }
    .profile-avatar { width: 10vw; height: 10vw; min-width: 100px; min-height: 100px; max-width: 150px; max-height: 150px; border-radius: 4px; background-size: cover; border: 3px solid transparent; transition: 0.2s; background-image: url('https://blogger.googleusercontent.com/img/a/AVvXsEjz7MoPdB747GVdrn5uuOeZPQJci0Xmgeal3zCnzJybu8xuoZMhDioea_lfFuMvq6tsnvXexltLXPulaK1wPZ1IB8ktYVyqVnphgEtJtNQedWjwFJn54DZZRPv3hHjoh1q-M9quzWYwyd6ZaZVi77lClVp8P8aM7BGQWfU0CDle_dz3bPsafSaYY00sbYE=s0100'); }
    .profile-item:hover .profile-avatar { border-color: white; }
    .profile-name { margin-top: 15px; color: grey; font-size: 1.2vw; transition: 0.2s; font-weight: 500; }
    .profile-item:hover .profile-name { color: white; }

    /* === NAVBAR === */
    .nav { position: fixed; top: 0; width: 100%; height: 68px; padding: 0 4%; display: flex; align-items: center; justify-content: space-between; z-index: 100; transition: 0.4s; background: linear-gradient(to bottom, rgba(0,0,0,0.7) 10%, transparent); }
    .nav.black { background-color: #000000; }

    /* WIDGET STYLES */
    .header-section { display: flex; align-items: center; }
    .header-widget h1 { color: var(--net-red); font-size: 25px; font-weight: 900; text-transform: uppercase; margin: 0; cursor: pointer; }
    .header-widget img { max-height: 40px; }
    .header-widget p { display: none; }

    .menu-section { margin-left: 20px; }
    .menu-widget ul { display: flex; list-style: none; gap: 20px; padding: 0; margin: 0; }
    .menu-widget a { color: #e5e5e5; text-decoration: none; font-size: 14px; font-weight: 500; transition: 0.2s; }
    .menu-widget a:hover { color: #b3b3b3; }

    /* OGFLIX SHARING WIDGETS */
    .ogflix-share{margin:18px 4% 20px;padding:10px 12px;border:1px solid rgba(255,255,255,.10);border-radius:12px;background:linear-gradient(145deg,rgba(255,255,255,.055),rgba(255,255,255,.015));box-shadow:0 10px 26px rgba(0,0,0,.22)}
    .ogflix-share-head{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:8px}
    .ogflix-share-title{display:flex;align-items:center;gap:8px;color:#fff;font-size:12px;font-weight:950;letter-spacing:.08em;text-transform:uppercase}
    .ogflix-share-title i{display:grid;place-items:center;width:25px;height:25px;border-radius:7px;background:#e50914;color:#fff;font-size:14px;box-shadow:0 5px 12px rgba(229,9,14,.22)}
    .ogflix-share-subtitle{color:#777;font-size:9px;font-weight:700;text-transform:uppercase;letter-spacing:.05em}
    .ogflix-share-buttons{display:grid;grid-template-columns:repeat(9,minmax(0,1fr));gap:6px}
    .ogflix-share-btn{position:relative;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;min-height:48px;min-width:48px;padding:6px 3px;border:1px solid rgba(255,255,255,.075);border-radius:8px;background:rgba(255,255,255,.035);color:#fff!important;text-decoration:none!important;font-size:7px;font-weight:900;letter-spacing:.025em;text-transform:uppercase;cursor:pointer;transition:transform .15s,background .15s,border-color .15s,box-shadow .15s}
    .ogflix-share-btn i{font-size:50px;line-height:3}
    .ogflix-share-btn span{display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100%; display: none !important;}
    .ogflix-share-btn:hover{transform:translateY(-2px);background:rgba(255,255,255,.09);border-color:rgba(255,255,255,.22);box-shadow:0 7px 14px rgba(0,0,0,.22)}
    .ogflix-share-btn:focus-visible{outline:2px solid #fff;outline-offset:2px}
    .ogflix-share-btn.facebook:hover{background:#1877f2}.ogflix-share-btn.x:hover{background:#000}.ogflix-share-btn.whatsapp:hover{background:#25d366}.ogflix-share-btn.telegram:hover{background:#229ed9}.ogflix-share-btn.reddit:hover{background:#ff4500}.ogflix-share-btn.linkedin:hover{background:#0a66c2}.ogflix-share-btn.pinterest:hover{background:#bd081c}.ogflix-share-btn.threads:hover{background:#111}.ogflix-share-btn.bluesky:hover{background:#1185fe}.ogflix-share-btn.tumblr:hover{background:#36465d}.ogflix-share-btn.vk:hover{background:#0077ff}.ogflix-share-btn.line:hover{background:#06c755}.ogflix-share-btn.email:hover{background:#555}.ogflix-share-btn.sms:hover{background:#555}.ogflix-share-btn.instagram:hover{background:#d62976}.ogflix-share-btn.tiktok:hover{background:#111}.ogflix-share-btn.copy:hover{background:#e50914}.ogflix-share-btn.more:hover{background:#555}
    .ogflix-share-status{min-height:12px;margin-top:6px;color:#aaa;font-size:9px;font-weight:800;text-align:center}
    .ogflix-share-home{display:none!important}
    @media(max-width:900px){.ogflix-share-buttons{grid-template-columns:repeat(6,minmax(0,1fr))}}
    @media(max-width:640px){.ogflix-share{margin:14px 3% 18px;padding:8px}.ogflix-share-head{margin-bottom:7px}.ogflix-share-subtitle{display:none}.ogflix-share-buttons{grid-template-columns:repeat(5,minmax(0,1fr));gap:5px}.ogflix-share-btn{min-height:44px;border-radius:7px}.ogflix-share-btn i{font-size:18px}.ogflix-share-btn span{font-size:6.5px}}

    @media(max-width: 768px) { .menu-section { display: none; } }

    /* MOBILE MENU */
    .mobile-menu { position: fixed; top: 68px; left: 0; width: 100%; background: #141414; border-top: 1px solid #333; display: flex; flex-direction: column; padding: 20px; gap: 20px; z-index: 90; transform: translateY(-150%); transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1); }
    .mobile-menu.open { transform: translateY(0); }
    .mobile-link { font-size: 16px; font-weight: 700; color: #e5e5e5; text-decoration: none; }
    .mobile-link:hover { color: white; }
    .mobile-join-trigger{display:block;width:100%;border:0;background:transparent;text-align:left;padding:0;color:#fff;cursor:pointer;font:inherit}

    /* === HERO BANNER === */
    .banner { width: 100%; background-size: cover; background-position: top top; position: relative; color: white; }
    @media(max-width: 767px) { .banner { height: 65vh; min-height: 400px; background-position: center; } .banner-title { font-size: 1.5rem !important; max-width: 100% !important; } .banner-desc { display: none !important; } }
    @media(min-width: 768px) { .banner { height: 90vh; max-height: 850px; } .banner-title { font-size: 4rem; max-width: 100%; } .banner-desc { display: -webkit-box; } }
    .banner-contents { margin-left: 4%; height: 100%; display: flex; flex-direction: column; justify-content: center; padding-top: 0px; position: relative; z-index: 10; }
    .banner-title { font-weight: 800; padding-bottom: 0.3rem; text-shadow: 2px 2px 4px rgba(0,0,0,0.5); line-height: 1.1; }
    .banner-desc { width: 100%; max-width: 600px; line-height: 1.3; padding-top: 1rem; font-size: 1.2rem; text-shadow: 2px 2px 4px rgba(0,0,0,0.5); font-weight: 500; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }
    .banner-btns { margin-top: 1.5rem; display: flex; gap: 1rem; }
    .btn { cursor: pointer; outline: none; border: none; font-weight: 700; border-radius: 4px; padding: 0.8rem 2.4rem; display: flex; align-items: center; gap: 10px; transition: 0.2s; font-size: 1.2rem; }
    .btn-play { background-color: white; color: black; }
    .btn-more { background-color: rgba(109, 109, 110, 0.7); color: white; }
    .banner-fade { height: 10rem; background-image: linear-gradient(180deg, transparent, rgba(20,20,20,0.61), #000000); position: absolute; bottom: 0; width: 100%; z-index: 1; }

    /* === ROWS & GRIDS === */
    .row { margin: 0px 0; padding-left: 4%; position: relative; }
    .row-title { font-size: 1.4vw; font-weight: 600; margin-bottom: 10px; color: #e5e5e5; display: inline-block; cursor: pointer; }
    @media(max-width: 768px) { .row-title { font-size: 18px; } }
    .row-posters { display: flex; overflow-y: hidden; overflow-x: scroll; padding: 10px 0 20px 0; gap: 10px; scrollbar-width: none; align-items: center; }
    .row-posters::-webkit-scrollbar { display: none; }
    .row-poster { flex: 0 0 auto; width: 160px; aspect-ratio: 2/3; object-fit: cover; border-radius: 4px; transition: transform 450ms; cursor: pointer; }
    @media(max-width: 768px) { .row-poster { width: 120px; } }
    .row-poster:hover { transform: scale(1.08); opacity: 1; z-index: 10; }

    /* TOP 10 */
    .rank-container { position: relative; flex: 0 0 auto; width: 160px; height: 180px; display: flex; align-items: center; cursor: pointer; transition: transform 450ms; margin-right: 10px; }
    @media(min-width: 768px) { .rank-container { width: 240px; height: 200px; margin-right: 20px; } }
    .rank-num { font-size: 120px; font-weight: 900; color: #000; -webkit-text-stroke: 4px #595959; position: absolute; left: -15px; bottom: 0; line-height: 0.9; z-index: 1; letter-spacing: -10px; }
    .rank-img { height: 100%; width: 65%; object-fit: cover; border-radius: 4px; position: absolute; right: 0; z-index: 2; }
    .rank-container:hover { transform: scale(1.05); z-index: 10; }

    /* FEATURED RANDOM CAROUSEL */
    .featured-carousel { position: relative; overflow: hidden; }
    .featured-carousel-track { display: flex; gap: 14px; overflow-x: auto; scroll-behavior: smooth; scrollbar-width: none; padding: 10px 4% 0px 4%; }
    .featured-carousel-track::-webkit-scrollbar { display: none; }
    .featured-card { flex: 0 0 180px; aspect-ratio: 2/3; position: relative; border-radius: 6px; overflow: hidden; cursor: pointer; background: #151515; transition: transform .35s ease; }
    .featured-card:hover { transform: scale(1.06); z-index: 5; }
    .featured-card img { width: 100%; height: 100%; object-fit: cover; display: block; }
    .featured-card-overlay { position: absolute; inset: auto 0 0 0; padding: 5px 10px 10px; background: linear-gradient(transparent, rgba(0,0,0,.9)); color: #fff; font-weight: 700; font-size: 14px; }
    .carousel-arrow { position: absolute; top: 50%; transform: translateY(-50%); z-index: 10; width: 42px; height: 58px; border: 0; border-radius: 4px; background: rgba(0,0,0,.72); color: #fff; font-size: 30px; cursor: pointer; display: flex; align-items: center; justify-content: center; }
    .carousel-arrow:hover { background: rgba(0,0,0,.92); }
    .carousel-prev { left: 8px; }
    .carousel-next { right: 8px; }
    @media(max-width: 768px) {
        .featured-card { flex-basis: 130px; }
        .carousel-arrow { width: 34px; height: 48px; font-size: 24px; }
    }

    /* === BOSSed UP WIDE PROMO BANNER === */
    .bossed-up-wide-banner{
      width:min(100%,1400px);
      min-height:180px;
      margin:42px auto 22px;
      padding:34px clamp(24px,5vw,70px);
      position:relative;
      overflow:hidden;
      display:flex;
      align-items:center;
      justify-content:space-between;
      gap:30px;
      border:1px solid rgba(255,255,255,.12);
      border-radius:16px;
      background:
        radial-gradient(circle at 85% 50%,rgba(229,9,20,.34),transparent 34%),
        linear-gradient(110deg,#000000 0%,#000 55%,#000000 100%);
      box-shadow:0 18px 55px rgba(0,0,0,.42);
      box-sizing:border-box;
    }
    .bossed-up-wide-banner:before{
      content:'';
      position:absolute;
      inset:0;
      background:linear-gradient(90deg,transparent 0%,rgba(229,9,20,.08) 48%,transparent 100%);
      pointer-events:none;
    }
    .bossed-up-wide-banner-copy{position:relative;z-index:2;max-width:780px;}
    .bossed-up-wide-banner-kicker{margin:0 0 7px;color:#e50914;font-size:12px;font-weight:900;letter-spacing:.16em;text-transform:uppercase;}
    .bossed-up-wide-banner-title{margin:0;color:#fff;font-size:clamp(24px,4vw,50px);line-height:.98;font-weight:950;letter-spacing:-.04em;text-transform:uppercase;text-shadow:0 4px 18px rgba(0,0,0,.7);}
    .bossed-up-wide-banner-text{margin:10px 0 0;color:#cfcfcf;font-size:15px;line-height:1.45;max-width:650px;}
    .bossed-up-wide-banner-badge{position:relative;z-index:2;flex:0 0 auto;display:flex;align-items:center;justify-content:center;width:116px;height:116px;border:1px solid rgba(255,255,255,.2);border-radius:50%;background:rgba(0,0,0,.48);box-shadow:0 0 0 8px rgba(229,9,20,.06),0 12px 35px rgba(0,0,0,.5);color:#fff;text-align:center;font-size:12px;font-weight:900;line-height:1.15;letter-spacing:.08em;text-transform:uppercase;}
    .bossed-up-wide-banner-badge span{color:#e50914;display:block;font-size:24px;margin-bottom:3px;}
    @media(max-width:768px){
      .bossed-up-wide-banner{width:calc(100% - 16px);min-height:145px;margin:30px auto 18px;padding:25px 20px;border-radius:13px;gap:14px;}
      .bossed-up-wide-banner-text{font-size:13px;margin-top:7px;}
      .bossed-up-wide-banner-badge{width:78px;height:78px;font-size:9px;flex-basis:78px;}
      .bossed-up-wide-banner-badge span{font-size:18px;}
    }

    /* === FEATURED CINEMATIC BANNER SLIDER === */
    .featured-banner-section { position: relative; margin: 45px 4% 35px; overflow: hidden; border-radius: 10px; background: #080808; box-shadow: 0 18px 60px rgba(0,0,0,.45); }
    .featured-banner-heading { display:flex; align-items:center; justify-content:space-between; padding:18px 24px 12px; position:relative; z-index:4; }
    .featured-banner-heading h2 { margin:0; color:#fff; font-size:22px; font-weight:900; text-transform:uppercase; letter-spacing:.04em; }
    .featured-banner-slider { position:relative; width:100%; overflow:hidden; }
    .featured-banner-track { display:flex; width:100%; transition:transform .7s cubic-bezier(.22,.61,.36,1); }
    .featured-banner-slide { min-width:100%; height:430px; position:relative; background:#111 center/cover no-repeat; cursor:pointer; }
    .featured-banner-slide:before { content:''; position:absolute; inset:0; background:linear-gradient(90deg,rgba(0,0,0,.94) 0%,rgba(0,0,0,.72) 34%,rgba(0,0,0,.18) 72%,rgba(0,0,0,.55) 100%),linear-gradient(0deg,rgba(0,0,0,.75),transparent 45%); }
    .featured-banner-content { position:absolute; left:5%; bottom:48px; max-width:650px; z-index:2; }
    .featured-banner-badge { display:inline-flex; align-items:center; gap:7px; padding:7px 12px; border-radius:4px; background:#e50914; color:#fff; font-size:12px; font-weight:900; text-transform:uppercase; letter-spacing:.08em; margin-bottom:14px; }
    .featured-banner-title { margin:0 0 12px; color:#fff; font-size:clamp(24px,4vw,50px); line-height:1.02; font-weight:900; text-shadow:2px 3px 10px #000; }
    .featured-banner-description { margin:0 0 20px; max-width:620px; color:#ddd; font-size:16px; line-height:1.5; display:-webkit-box; -webkit-line-clamp:3; -webkit-box-orient:vertical; overflow:hidden; }
    .featured-banner-watch { display:inline-flex; align-items:center; gap:9px; padding:12px 22px; border:0; border-radius:4px; background:#fff; color:#000; font-weight:900; font-size:15px; cursor:pointer; text-decoration:none; }
    .featured-banner-watch:hover { background:#ddd; transform:translateY(-1px); }
    .featured-banner-arrow { position:absolute; top:50%; transform:translateY(-50%); z-index:5; width:46px; height:64px; border:0; border-radius:5px; background:rgba(0,0,0,.62); color:#fff; font-size:31px; cursor:pointer; display:flex; align-items:center; justify-content:center; }
    .featured-banner-arrow:hover { background:rgba(0,0,0,.9); }
    .featured-banner-prev { left:14px; }
    .featured-banner-next { right:14px; }
    .featured-banner-dots { position:absolute; left:50%; bottom:16px; transform:translateX(-50%); z-index:6; display:flex; gap:7px; }
    .featured-banner-dot { width:8px; height:8px; padding:0; border:0; border-radius:50%; background:rgba(255,255,255,.45); cursor:pointer; transition:.2s; }
    .featured-banner-dot.active { width:24px; border-radius:5px; background:#fff; }
    .featured-banner-loading,.featured-banner-empty { padding:50px 20px; color:#777; text-align:center; }
    @media(max-width:768px) {
        .featured-banner-section { margin:30px 3% 25px; border-radius:7px; }
        .featured-banner-heading { padding:15px 16px 10px; }
        .featured-banner-heading h2 { font-size:18px; }
        .featured-banner-slide { height:430px; }
        .featured-banner-content { left:20px; right:20px; bottom:42px; }
        .featured-banner-title { font-size:26px; }
        .featured-banner-description { font-size:14px; -webkit-line-clamp:3; }
        .featured-banner-arrow { width:36px; height:50px; font-size:24px; }
        .featured-banner-prev { left:7px; }
        .featured-banner-next { right:7px; }
    }

    /* SEARCH GRID */
    .search-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; padding: 20px; }
    @media(min-width: 768px) { .search-grid { grid-template-columns: repeat(6, 1fr); gap: 15px; padding: 0px; } }

    /* === PLAYER UI === */
    .modal-overlay { position: fixed; inset: 0; background: #000000; z-index: 200; overflow-y: auto; transform: translateY(100%); transition: 0.3s; }
    .modal-overlay.active { transform: translateY(0); }
    .player-responsive { width: 100%; position: relative; padding-top: 56.25%; background: black; overflow: hidden; }
    @media(min-width: 1400px) { .player-responsive { padding-top: 0; height: 80vh; max-width: 1600px; margin: 0 auto; } }
    .player-responsive iframe { position: absolute; top: 0; left: 0; width: 100%; height: 100%; border: 0; }
    .back-btn { position: absolute; top: 20px; left: 20px; z-index: 20; color: white; font-size: 40px; cursor: pointer; filter: drop-shadow(0 0 5px black); }
    .modal-info { padding: 30px 4%; max-width: 1500px; margin: 0 auto; display: grid; grid-template-columns: minmax(0, 1fr) minmax(260px, 380px); gap: 40px; align-items: start; }
    @media(max-width: 900px) { .modal-info { grid-template-columns: 1fr; } }
    .media-description { min-width: 0; }
    .cover-wrap { width: 100%; max-width: 380px; margin-left: auto; }
    .cover-image { display:block; width: 100%; aspect-ratio: 2/3; object-fit: cover; border-radius: 8px; box-shadow: 0 15px 45px rgba(0,0,0,.45); }
    .cover-caption { color:#888; font-size:12px; margin-top:8px; text-align:center; }
    .description-label { color:#999; font-size:13px; text-transform:uppercase; letter-spacing:.08em; font-weight:800; margin-bottom:8px; }
    .platform-section { margin-top: 0px; padding-top: 24px; border-top: 1px solid #333; }
    .platform-grid { display:flex; flex-wrap:wrap; gap:10px; }
    .platform-btn { display:inline-flex; align-items:center; gap:8px; padding:10px 16px; border-radius:6px; background:#222; color:#fff; border:1px solid #444; font-weight:700; text-decoration:none; cursor:pointer; transition:.2s; }
    .platform-btn:hover { background:#333; border-color:#777; transform:translateY(-1px); }
    .platform-btn.youtube { background:#e50914; border-color:#e50914; }
    .platform-btn.music-service { background:#171717; }
    .platform-label { color:#999; font-size:13px; margin-bottom:10px; text-transform:uppercase; letter-spacing:.08em; font-weight:700; }
    .album-link-service {
        font-weight: 800;
    }

    .platform-note { color:#777; font-size:12px; margin-top:10px; }

    /* EPISODES & DOWNLOADS */
    .season-tabs { display: flex; gap: 15px; overflow-x: auto; padding-bottom: 10px; border-bottom: 1px solid #333; margin-bottom: 15px; }
    .tab-btn { background: transparent; color: #999; padding: 8px 0; font-weight: 700; cursor: pointer; border-radius: 0; white-space: nowrap; font-size: 16px; border-bottom: 3px solid transparent; }
    .tab-btn.active { color: white; border-bottom-color: var(--net-red); }
    .ep-row { display: flex; align-items: center; padding: 10px; border-bottom: 1px solid #2a2a2a; transition: 0.2s; gap: 15px; border-radius: 4px; }
    .ep-row:hover { background: #222; }
    .ep-idx { color: #d2d2d2; font-size: 1.5em; font-weight: bold; width: 20px; flex-shrink: 0; text-align: center; }
    .ep-thumb-wrap { width: 120px; aspect-ratio: 16/9; position: relative; flex-shrink: 0; border-radius: 4px; overflow: hidden; }
    .ep-thumb { width: 100%; height: 100%; object-fit: cover; }
    .ep-meta { flex: 1; min-width: 0; }
    .ep-title { font-weight: 700; font-size: 0.95em; color: white; margin-bottom: 4px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    .dl-icon-btn { color: #e5e5e5; font-size: 24px; padding: 10px; border-radius: 50%; transition: 0.2s; cursor: pointer; display: flex; align-items: center; justify-content: center; }
    .dl-icon-btn:hover { background: rgba(255,255,255,0.1); color: white; }
    .dl-movie-row { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 0px; border-top: 1px solid #333; padding-top: 20px; }
    .dl-btn { border: 1px solid #4ade80; color: #4ade80; padding: 10px 24px; border-radius: 4px; font-weight: 700; font-size: 14px; text-transform: uppercase; transition: 0.2s; text-decoration: none; display: inline-flex; align-items: center; gap: 8px; }
    .dl-btn:hover { background: #4ade80; color: black; }
    .youtube-source { background:#e50914 !important; color:#fff !important; }
    .youtube-source:hover { background:#b20710 !important; }

    /* YOU MAY LIKE THIS */
    .you-may-like {
        max-width: 1500px;
        margin: 10px auto 60px;
        padding: 0 4%;
    }
    .you-may-like-title {
        color: #fff;
        font-size: 22px;
        font-weight: 800;
        margin: 0 0 18px;
    }
    .you-may-like-title::before {
        content: '';
        display: inline-block;
        width: 4px;
        height: 22px;
        background: var(--net-red);
        margin-right: 10px;
        vertical-align: -3px;
        border-radius: 2px;
    }
    .you-may-like-grid {
        display: grid;
        grid-template-columns: repeat(6, minmax(0, 1fr));
        gap: 16px;
    }
    .you-may-like-card {
        display: block;
        position: relative;
        overflow: hidden;
        border-radius: 6px;
        background: #181818;
        text-decoration: none;
        transition: transform .25s ease, box-shadow .25s ease;
        cursor: pointer;
    }
    .you-may-like-card:hover {
        transform: scale(1.04);
        box-shadow: 0 12px 35px rgba(0,0,0,.55);
        z-index: 2;
    }
    .you-may-like-poster {
        width: 100%;
        aspect-ratio: 2 / 3;
        object-fit: cover;
        display: block;
        background: #222;
    }
    .you-may-like-info { padding: 10px; }
    .you-may-like-name {
        color: #fff;
        font-size: 14px;
        font-weight: 700;
        line-height: 1.3;
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
    }
    .you-may-like-meta {
        color: #888;
        font-size: 11px;
        margin-top: 4px;
    }
    @media(max-width: 1200px) {
        .you-may-like-grid { grid-template-columns: repeat(5, minmax(0, 1fr)); }
    }
    @media(max-width: 900px) {
        .you-may-like-grid { grid-template-columns: repeat(4, minmax(0, 1fr)); }
    }
    @media(max-width: 600px) {
        .you-may-like-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 10px; }
        .you-may-like { padding: 0 3%; }
    }
    @media(max-width: 400px) {
        .you-may-like-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    }


