    .content-card-meta{color:#aaa;font-size:10px;margin-top:4px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
    /* ALL-TIME POPULAR POSTS - HOMEPAGE: 4 COLUMNS x 2 ROWS, NO SCROLLING */
