    @media(max-width:600px){#row-recommended .row-posters{grid-template-columns:repeat(4,minmax(0,1fr));gap:9px}}
    @media(max-width:430px){#row-recommended .row-posters{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}}
    @media(max-width:768px){.content-card{flex-basis:135px}.homepage-intro{padding:10 3% 8px}.homepage-intro-inner{padding:22px}.homepage-intro p{font-size:13px}}
