    .artist-strip .content-card img{object-fit:cover}
    .home-cta{margin:40px 4% 20px;padding:42px 35px;border-radius:10px;background:linear-gradient(135deg,#B8860B,#B8860B);border:1px solid rgba(255,255,255,.09);text-align:center}
    .home-cta h2{margin:0 0 8px;color:#000000;font-size:clamp(50px,3vw,60px);font-weight:900}
    .home-cta p{margin:0 auto 22px;color:#fff;max-width:720px;line-height:1.6}
    .home-cta-buttons{display:flex;justify-content:center;flex-wrap:wrap;gap:10px}
    .home-cta-btn{display:inline-flex;align-items:center;gap:8px;padding:12px 20px;border-radius:4px;background:#e50914;color:#fff;text-decoration:none;font-weight:900;font-size:13px}
    .home-cta-btn.secondary{background:#fff;color:#ff0000}
    .home-cta-btn:hover{transform:translateY(-2px);filter:brightness(1.08)}
    .label-page-heading{max-width:1400px;margin:0 auto 22px;padding:0 0px}.label-page-heading h1{margin:0;font-size:clamp(28px,4vw,46px);font-weight:800;color:#fff}.label-page-heading p{margin:6px 0 0;color:#9ca3af}.label-content-grid{max-width:1400px;margin:0 auto;padding:0 0px 50px;display:grid;grid-template-columns:repeat(auto-fill,minmax(170px,1fr));gap:20px}.label-content-card{min-width:0;text-decoration:none!important;color:inherit}.label-content-card img{display:block;width:100%;aspect-ratio:2/3;object-fit:cover;border-radius:12px;background:#151515}.label-empty{max-width:900px;margin:80px auto;padding:0px 25px;text-align:center;color:#9ca3af}.label-empty i{display:block;font-size:64px;margin-bottom:15px}.label-empty h2{color:#fff;margin:0 0 8px;font-size:30px}.home-empty{display:block;margin:0 4% 28px}.placeholder-section{padding:18px 0}.placeholder-heading{color:#fff;font-size:22px;font-weight:900;margin:0 0 14px}.placeholder-grid{display:flex;gap:14px;overflow:hidden}.placeholder-card{flex:0 0 180px;aspect-ratio:2/3;border-radius:8px;background:linear-gradient(145deg,#000000,#000000);border:1px solid rgba(255,255,255,.08);display:flex;align-items:center;justify-content:center;text-align:center;padding:18px;box-sizing:border-box}.placeholder-card-inner{color:#777}.placeholder-icon{font-size:32px;display:block;margin-bottom:10px;color:#555}.placeholder-title{font-size:12px;font-weight:800;text-transform:uppercase;letter-spacing:.08em;color:#aaa}.placeholder-copy{font-size:10px;line-height:1.5;margin-top:6px;color:#666}.featured-banner-empty{margin:0 4% 25px;min-height:220px;border:1px solid rgba(255,255,255,.08);border-radius:10px;background:linear-gradient(135deg,#000000,#000000);display:flex;align-items:center;justify-content:center;text-align:center;padding:0px;color:#777}.featured-banner-empty strong{color:#aaa}.home-placeholder-note{color:#666;font-size:11px;margin-top:8px}@media(max-width:768px){.placeholder-card{flex-basis:135px}.placeholder-grid{gap:10px}}
    /* === LABEL PAGES === */
    .label-page-shell{width:100%;padding:0px clamp(18px,4vw,58px) 0px;box-sizing:border-box}
    .label-page-heading{max-width:none;margin:0 0 26px;padding:0}
    .label-page-heading h1{margin:0;font-size:clamp(30px,3.6vw,52px);font-weight:900;letter-spacing:-.04em;color:#fff}
    .label-page-heading p{margin:7px 0 0;color:#8f8f8f;font-size:13px;font-weight:700}
    .label-section{margin:0 0 42px}
    .label-section-head{display:flex;align-items:flex-end;justify-content:space-between;gap:20px;margin:0 0 13px}
    .label-section-title{margin:0;color:#fff;font-size:clamp(19px,1.55vw,25px);font-weight:900;letter-spacing:-.025em}
    .label-section-title:before{content:'';display:inline-block;width:4px;height:20px;margin-right:9px;vertical-align:-2px;border-radius:3px;background:#B8860B}
    .label-section-subtitle{margin:5px 0 0 13px;color:#777;font-size:11px;font-weight:700}
    .label-section-link{display:inline-flex;align-items:center;gap:6px;color:#aaa;text-decoration:none;font-size:11px;font-weight:900;text-transform:uppercase;letter-spacing:.07em;white-space:nowrap}
    .label-section-link:hover{color:#fff}
    .label-horizontal{display:flex;gap:14px;overflow-x:auto;padding:8px 4px 20px 2px;scrollbar-width:none;scroll-behavior:smooth;scroll-snap-type:x proximity;-webkit-overflow-scrolling:touch;cursor:grab}.label-horizontal:active{cursor:grabbing}
    .label-horizontal::-webkit-scrollbar{display:none}
    .label-card{flex:0 0 180px;position:relative;aspect-ratio:2/3;border-radius:9px;overflow:hidden;background:#111;text-decoration:none;color:#fff;box-shadow:0 10px 30px rgba(0,0,0,.28);transition:transform .3s ease,box-shadow .3s ease}
    .label-card:hover{transform:scale(1.055) translateY(-4px);box-shadow:0 20px 45px rgba(0,0,0,.58);z-index:3}
    .label-card img{width:100%;height:100%;object-fit:cover;display:block}
    .label-card:after{content:'';position:absolute;inset:45% 0 0;background:linear-gradient(transparent,rgba(0,0,0,.96))}
    .label-card-info{position:absolute;left:10px;right:10px;bottom:10px;z-index:2}
    .label-card-title{font-size:13px;font-weight:900;line-height:1.25;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
    .label-card-meta{margin-top:4px;color:#aaa;font-size:10px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
    .label-rank{position:absolute;left:6px;top:4px;z-index:3;font-size:72px;font-weight:900;line-height:1;color:#000;-webkit-text-stroke:2px rgba(255,255,255,.72);text-shadow:0 5px 18px rgba(0,0,0,.75);letter-spacing:-.08em}
    .label-all-grid{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:18px;padding:8px 2px 28px;overflow:visible;width:100%}
    .label-all-grid .label-card{width:100%;min-width:0;aspect-ratio:2/3;scroll-snap-align:none}
    @media(max-width:1400px){.label-all-grid{grid-template-columns:repeat(5,minmax(0,1fr))}}
    @media(max-width:1100px){.label-all-grid{grid-template-columns:repeat(4,minmax(0,1fr))}}
    @media(max-width:760px){.label-page-shell{padding:92px 3% 45px}.label-all-grid{grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.label-section{margin-bottom:32px}.label-section-link{font-size:10px}}
    @media(max-width:480px){.label-all-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}}
    .menu-widget a.label-active{color:#fff;font-weight:900}
    .menu-widget a.label-active:after{right:0;background:#B8860B}
    .mobile-link.label-active{color:#fff}


    @media(max-width:768px){.label-all-grid{gap:11px}.label-all-grid .label-card{width:100%}.search-grid{gap:12px;padding:0 2px}.search-grid .row-poster{flex-basis:140px;width:140px;height:210px}}
    /* ' */
    .site-footer { padding: 50px 10%; color: #808080; font-size: 13px; margin-top: 50px; max-width: 1000px; margin-left: auto; margin-right: auto; }
    .footer-links { display: grid; grid-template-columns: repeat(4, 1fr); gap: 15px; margin-bottom: 20px; }
    .footer-links a { color: #808080; text-decoration: none; }
    .footer-links a:hover { text-decoration: underline; }

    /* UTILS */
    #post-body-raw { display: none; }
    .ogflix-page-content{
      width:min(1180px,calc(100% - 32px));
      max-width:1800px;
      margin:68px auto 70px;
      padding:0 clamp(20px,4vw,48px);
      border-radius:16px;
      background: #000000;
      box-shadow:0 24px 70px rgba(0,0,0,.45);
      min-width:0;
    }
    .ogflix-page-title{
      margin:0 0 24px;
      color:#fff;
      font-size:clamp(28px,4vw,52px);
      line-height:1.05;
      font-weight:900;
      letter-spacing:-.04em;
    }
    .ogflix-page-body{
      color:#ddd;
      font-size:16px;
      line-height:1.75;
      overflow-wrap:anywhere;
    }
    .ogflix-page-body img,.ogflix-page-body iframe,.ogflix-page-body video{max-width:1800;height:auto;}
    .ogflix-page-body iframe{min-height:0;}
    @media(max-width:768px){
      .ogflix-page-content{width:calc(100% - 20px);margin:62px auto 45px;padding:0 18px;border-radius:12px;}
      .ogflix-page-title{font-size:32px;}
      .ogflix-page-body{font-size:15px;line-height:1.65;}
    }
    .search-box { position: fixed; top: 0; left: 0; width: 100%; height: 70px; background: #141414; z-index: 110; display: flex; align-items: center; padding: 0 4%; transform: translateY(-100%); transition: 0.3s; }
    .search-box.open { transform: translateY(0); }
    .search-close { font-size: 30px; cursor: pointer; color: white; margin-left: 20px; }


/* OGFlix Bossed Up TV */
#bossed-up-tv-section{width:100%;margin:2px 0;padding:0}
.bossed-up-tv-wrap{display:grid;grid-template-columns:minmax(0,1.9fr) minmax(260px,1fr);gap:2px;align-items:stretch}
.bossed-up-tv-frame{height:390px;position:relative;background:#000000;border:0px solid #000000;border-radius:20px;box-shadow:0 8px 5px rgba(0,0,0,0),inset 0 0 0 2px #000000;padding:12px}
.bossed-up-tv-bezel{height:390px;min-height:390px;background:#000;border-radius:0px;overflow:hidden;box-shadow:inset 0 0 5px rgba(0,0,0,.95)}
.bossed-up-tv-screen{width:100%;height:390px;border:0;display:block;background:#000}
.bossed-up-tv-empty{min-height:390px;display:flex;align-items:center;justify-content:center;color:#777;text-align:center;font-size:15px;padding:30px}
.bossed-up-tv-controls{display:flex;gap:8px;justify-content:center;flex-wrap:wrap;margin-top:12px}
.bossed-up-tv-dot{width:9px;height:9px;border-radius:50%;border:0;background:#000;cursor:pointer;padding:0}
.bossed-up-tv-dot.active{background:#fff;transform:scale(1.2)}
.bossed-up-panel{background:linear-gradient(145deg,#000000,#000000);border:1px solid #000000;border-radius:20px;padding:24px;box-shadow:0 18px 5px rgba(0,0,0,.4);display:flex;flex-direction:column}
.bossed-up-kicker{font-size:12px;letter-spacing:2.5px;text-transform:uppercase;color:#999;margin-bottom:6px}
.bossed-up-title{font-size:30px;font-weight:900;line-height:1.05;margin:0 0 8px;color:#fff}
.bossed-up-copy{font-size:14px;color:#aaa;margin:0 0 18px;line-height:1.5}
.bossed-up-channels{display:grid;grid-template-columns:1fr 1fr;gap:10px;overflow:auto}
.bossed-up-channel{border:1px solid #000000;background:#111;color:#fff;border-radius:12px;padding:12px;text-align:left;cursor:pointer}
.bossed-up-channel:hover,.bossed-up-channel.active{border-color:#fff;background:#000000}
.bossed-up-channel-number{font-size:11px;color:#888;letter-spacing:1px}
.bossed-up-channel-name{display:block;font-weight:800;font-size:14px;margin-top:3px}
.bossed-up-now{margin-top:auto;border-top:1px solid #000;padding-top:15px;color:#bbb;font-size:13px}
.bossed-up-now strong{color:#fff}
@media(max-width:800px){.bossed-up-tv-wrap{grid-template-columns:1fr}.bossed-up-tv-screen,.bossed-up-tv-empty{height:280px;min-height:280px}.bossed-up-channels{max-height:280px}}

    /* PROFILE / JOIN: hidden until JOIN is selected; never blocks normal page loading. */
    .profile-gate { display:flex; opacity:0; pointer-events:none; visibility:hidden; }
    .profile-gate.join-open { opacity:1; pointer-events:auto; visibility:visible; transform:none; }
    .profile-gate .profile-avatar { background-image:url('https://blogger.googleusercontent.com/img/a/AVvXsEgDcvU2FFspUtgsZz3XeFcC1NIMeqbESkXYcglW6odS8mhOwgNDJ1LqUZs1oIufkMwxQJnluSujralPeC3ttS3TwW9W7a3IGtMWJytoa03CY9kuXnbWGbMfEoenECY17IWXkEfvFkvyxmeSe_lSPJ0eubGVO_Pvi83SQ9J6O0i3S-q5CuafYlG40KugeCE=s1600'); }
    .join-close { margin-top:28px; border:1px solid #555; background:transparent; color:#aaa; padding:10px 24px; border-radius:4px; cursor:pointer; text-transform:uppercase; letter-spacing:.14em; font-size:12px; }
    .join-close:hover { border-color:#fff; color:#fff; }
    .join-profile-title { color:#fff; font-size:clamp(30px,4vw,52px); font-weight:900; margin:0 0 28px; text-transform:uppercase; letter-spacing:-.03em; }
    .join-profile-subtitle { color:#888; font-size:13px; margin:-14px 0 28px; }

    /* Mobile header/menu: no visual gap between menu button and header image. */
    @media(max-width:768px){
      .nav{gap:0!important}
      .nav > .flex.items-center.w-full{gap:0!important}
      .nav .bx-menu{margin-right:0!important}
      .nav .header-section{margin-left:0!important;padding-left:0!important}
      .nav .header-widget{margin-left:0!important;padding-left:0!important}
      .mobile-menu{top:62px!important}
    }



    /* Hide internal post metadata/quality elements from viewers while preserving their attributes for scripts. */
    [data-meta],
    [data-quality] { display:none !important; }


    [data-meta],[data-quality],.data-meta,.data-quality{display:none !important;}

    /* OGFlix: hide internal metadata */
    [data-meta],[data-quality],.data-meta,.data-quality{display:none !important;}

    /* Bossed Up TV thumbnail fallback/preview */
    .bossed-up-tv-preview{position:relative;width:100%;min-height:390px;background:#000 center/cover no-repeat;display:flex;align-items:center;justify-content:center;overflow:hidden}
    .bossed-up-tv-preview:before{content:'';position:absolute;inset:0;background:#000000;}
    .bossed-up-tv-preview-info{position:relative;z-index:2;text-align:center;padding:24px;max-width:85%}
    .bossed-up-tv-preview-title{color:#fff;font-size:18px;font-weight:900;margin-bottom:14px;text-shadow:0 2px 12px rgba(0,0,0,.7)}
    .bossed-up-tv-play{border:0;border-radius:999px;padding:12px 20px;background:#000000;color:#fff;font-size:13px;font-weight:900;cursor:pointer;box-shadow:0 8px 24px rgba(0,0,0,.4)}
    .bossed-up-tv-play:hover{filter:brightness(1.08);transform:translateY(-1px)}
    .bossed-up-channel{overflow:hidden}
    .bossed-up-channel-thumb{width:100%;aspect-ratio:16/9;display:block;object-fit:cover;border-radius:8px;margin-bottom:8px;background:#000000}
    .bossed-up-channel-text{display:block}
    @media(max-width:800px){
      .bossed-up-tv-preview{min-height:280px}
      .bossed-up-channel-thumb{aspect-ratio:16/9}
    }


    .bossed-up-channel-name{font-size:14px;font-weight:900;letter-spacing:.02em}
    .bossed-up-channel-number{font-size:9px;color:#777;letter-spacing:1.4px}
    .bossed-up-tv-preview-channel{font-size:11px;color:#ddd;text-transform:uppercase;letter-spacing:1.5px;margin-bottom:12px}


/* =========================================================
   OGFLIX 2026 — PREMIUM VISUAL UPGRADE
   ========================================================= */
:root{
  --og-bg:#000000;
  --og-surface:#000000;
  --og-surface-2:#000000;
  --og-line:rgba(255,255,255,.09);
  --og-red:#e50914;
  --og-red-2:#b20710;
  --og-white:#fff;
  --og-muted:#9b9b9b;
  --og-shadow:0 24px 70px rgba(0,0,0,.55);
}

html{scroll-behavior:smooth}
body{
  background-color:#000000;
    linear-gradient(#000000,#000000 35%,#000000);
}
body:before{
  content:"";
  position:fixed;
  inset:0;
  pointer-events:none;
  z-index:-1;
  background-color:
    linear-gradient(rgba(0,0,0,0) 1px,transparent 1px),
    transparent;
  mask-image:linear-gradient(to bottom,black,transparent 75%);
}

/* Premium glass navigation */
.nav{
  height:72px;
  padding:0 clamp(18px,4vw,58px);
  background-color:#000000;
  backdrop-filter:blur(6px);
  -webkit-backdrop-filter:blur(5px);
}
.nav.black{
  background:rgba(5,5,5,.92);
  border-bottom:1px solid rgba(255,255,255,.07);
  box-shadow:0 10px 35px rgba(0,0,0,.35);
}
.header-widget img{
  max-height:42px;
  width:auto;
  filter:drop-shadow(0 5px 18px rgba(0,0,0,0));
}
.menu-widget ul{gap:26px}
.menu-widget a{
  position:relative;
  color:#cfcfcf;
  font-size:13px;
  letter-spacing:.02em;
}
.menu-widget a:after{
  content:"";
  position:absolute;
  left:0;right:100%;bottom:-9px;
  height:2px;
  background:var(--og-red);
  transition:right .25s ease;
}
.menu-widget a:hover{color:#fff}
.menu-widget a:hover:after{right:0}

.nav .bx-search{
  transition:transform .2s,color .2s;
}
.nav .bx-search:hover{transform:scale(1.12);color:#fff}

/* Search */
.search-box{
  height:76px;
  padding:0 clamp(18px,4vw,58px);
  background:rgba(8,8,8,.97);
  border-bottom:1px solid var(--og-line);
  box-shadow:0 15px 45px rgba(0,0,0,.45);
  backdrop-filter:blur(15px);
}
.search-box input::placeholder{color:#666}
.search-close{opacity:.75}
.search-close:hover{opacity:1}

/* Hero */
.banner{
  min-height:680px;
  height:min(88vh,900px);
  background-position:top center;
}
.banner:after{
  content:"";
  position:absolute;
  inset:0;
  background:
    radial-gradient(circle at 72% 35%,transparent 0,rgba(0,0,0,.08) 30%,rgba(0,0,0,.5) 100%),
    linear-gradient(90deg,rgba(0,0,0,.82) 0%,rgba(0,0,0,.42) 48%,rgba(0,0,0,.12) 100%);
  pointer-events:none;
}
.banner-contents{
  margin-left:clamp(5%,4vw,7%);
  padding-top:5px;
  max-width:720px;
}
.banner-title{
  font-size:clamp(36px,6vw,80px)!important;
  font-weight:900;
  letter-spacing:-.045em;
  text-shadow:0 8px 35px rgba(0,0,0,.75);
}
.banner-desc{
  max-width:650px;
  font-size:clamp(14px,1.3vw,19px);
  color:#ddd;
}
.banner-btns{gap:10px}
.btn{
  border-radius:7px;
  padding:.85rem 1.5rem;
  font-size:1rem;
  box-shadow:0 10px 30px rgba(0,0,0,.25);
}
.btn-play{
  background:#fff;
  color:#050505;
}
.btn-play:hover{background:#e8e8e8;transform:translateY(-2px)}
.btn-more{
  background:rgba(55,55,55,.8);
  border:1px solid rgba(255,255,255,.12);
}
.btn-more:hover{background:rgba(85,85,85,.9);transform:translateY(-2px)}
.banner-fade{
  height:16rem;
  background:linear-gradient(180deg,transparent 0%,rgba(5,5,5,.7) 45%,#050505 100%);
}

/* Premium Homepage Intro */
.homepage-intro{
  position:relative;
  padding:0 clamp(3%,4vw,6%) 18px;
}
.homepage-intro-inner{
  position:relative;
  overflow:hidden;
  padding:30px clamp(24px,4vw,52px) 32px;
  border:1px solid rgba(255,255,255,.12);
  border-radius:20px;
  background:
    radial-gradient(circle at 100% 0%,rgba(229,9,20,.24),transparent 30%),
    radial-gradient(circle at 0% 100%,rgba(255,255,255,.06),transparent 32%),
    linear-gradient(135deg,#080808 0%,#030303 55%,#0d0d0d 100%);
  box-shadow:0 22px 70px rgba(0,0,0,.55),inset 0 1px 0 rgba(255,255,255,.06);
}
.homepage-intro-inner:before{
  content:"";
  position:absolute;
  left:0;top:0;bottom:0;
  width:5px;
  background:linear-gradient(180deg,#ff2635 0%,#b3000d 55%,transparent 100%);
  box-shadow:0 0 24px rgba(229,9,20,.45);
}
.homepage-intro-inner:after{
  content:"";
  position:absolute;
  right:-90px;
  top:-110px;
  width:260px;
  height:260px;
  border-radius:50%;
  border:1px solid rgba(255,255,255,.07);
  box-shadow:0 0 0 35px rgba(255,255,255,.015),0 0 0 70px rgba(255,255,255,.01);
  pointer-events:none;
}
.homepage-kicker{
  display:inline-flex;
  align-items:center;
  gap:8px;
  margin-bottom:10px;
  color:#ff3b49;
  font-size:12px;
  font-weight:900;
  letter-spacing:.18em;
  text-transform:uppercase;
}
.homepage-kicker:before{
  content:"";
  width:28px;
  height:2px;
  background:#e50914;
  box-shadow:0 0 10px rgba(229,9,20,.7);
}
.homepage-intro h2{
  position:relative;
  z-index:1;
  margin:0 0 12px;
  color:#fff;
  font-size:clamp(30px,4vw,58px);
  line-height:.98;
  font-weight:950;
  letter-spacing:-.045em;
  text-transform:uppercase;
  text-shadow:0 5px 25px rgba(0,0,0,.55);
}
.homepage-intro p{
  position:relative;
  z-index:1;
  max-width:920px;
  margin:0;
  color:#b8b8b8;
  font-size:clamp(14px,1.2vw,16px);
  line-height:1.7;
}
@media(max-width:768px){
  .homepage-intro{padding:0 3% 14px}
  .homepage-intro-inner{padding:25px 20px 26px;border-radius:16px}
  .homepage-intro h2{font-size:34px;line-height:1}
  .homepage-intro p{font-size:13px;line-height:1.6}
}

/* Section headings */
.row{
  margin:34px 0;
  padding-left:clamp(3%,4vw,6%);
}
.section-heading .row-title,
.row-title{
  font-size:clamp(18px,1.45vw,24px);
  font-weight:900;
  letter-spacing:-.02em;
  color:#fff;
}
.section-heading .row-title:before{
  content:"";
  display:inline-block;
  width:4px;
  height:20px;
  margin-right:9px;
  vertical-align:-2px;
  border-radius:3px;
  background:#000000;
}

/* Content cards */
.content-card,
.featured-card,
.row-poster,
.you-may-like-card{
  box-shadow:0 10px 30px rgba(0,0,0,.25);
}
.content-card,
.featured-card{
  border-radius:9px;
}
.content-card:hover,
.featured-card:hover,
.row-poster:hover{
  transform:scale(1.065) translateY(-4px);
  box-shadow:0 20px 45px rgba(0,0,0,.55);
}
.content-card:after{
  background:linear-gradient(transparent 38%,rgba(0,0,0,.96));
}
.content-card-title{font-size:14px}
.content-card-meta{color:#b0b0b0}

/* Featured carousel */
.featured-banner-section{
  margin:55px clamp(3%,4vw,6%) 42px;
  border:1px solid rgba(255,255,255,.08);
  border-radius:16px;
  background:linear-gradient(145deg,#000,#000000);
  box-shadow:var(--og-shadow);
}
.featured-banner-heading{padding:20px 24px 14px}
.featured-banner-heading h2{
  font-size:clamp(18px,2vw,25px);
  letter-spacing:-.02em;
}
.featured-banner-slide{
  height:500px;
}
.featured-banner-slide:before{
  background:
    linear-gradient(90deg,rgba(0,0,0,.95) 0%,rgba(0,0,0,.68) 35%,rgba(0,0,0,.16) 76%,rgba(0,0,0,.62) 100%),
    linear-gradient(0deg,rgba(0,0,0,.82),transparent 50%);
}
.featured-banner-content{left:6%;bottom:58px}
.featured-banner-badge{
  background:var(--og-red);
  border-radius:5px;
  box-shadow:0 8px 25px rgba(229,9,20,.25);
}
.featured-banner-title{
  letter-spacing:-.045em;
}
.featured-banner-watch{
  border-radius:7px;
  box-shadow:0 10px 30px rgba(0,0,0,.35);
}
.featured-banner-arrow{
  width:48px;height:70px;
  background:rgba(0,0,0,.5);
  backdrop-filter:blur(8px);
}
.featured-banner-dot.active{background:var(--og-red)}

/* Bossed Up TV */
#bossed-up-tv-section{
  margin:60px clamp(3%,4vw,6%);
}
.bossed-up-tv-wrap{gap:8px}
.bossed-up-tv-frame{
  padding:12px;
  border:1px solid #000000;
  border-radius:22px;
  background:
    linear-gradient(145deg,#000000,#000000);
  box-shadow:0 25px 70px rgba(0,0,0,.6);
}
.bossed-up-tv-bezel{
  min-height:460px;
  border-radius:14px;
  box-shadow:inset 0 0 60px #000;
}
.bossed-up-tv-screen{height:460px}
.bossed-up-panel{
  border-radius:22px;
  border:1px solid rgba(255,255,255,.1);
  background:
    radial-gradient(circle at 100% 0%,rgba(229,9,20,.12),transparent 35%),
    linear-gradient(145deg,#000000,#000000);
}
.bossed-up-kicker{color:#e50914;font-weight:900}
.bossed-up-title{
  font-size:clamp(30px,3vw,46px);
  letter-spacing:-.045em;
}
.bossed-up-channel{
  border-radius:10px;
  transition:.2s ease;
}
.bossed-up-channel:hover{
  transform:translateY(-2px);
  border-color:#666;
}
.bossed-up-channel.active{
  border-color:#e50914;
  box-shadow:0 0 0 1px rgba(229,9,20,.25),0 10px 25px rgba(0,0,0,.25);
}

/* Player */
.modal-overlay{
  background:
    radial-gradient(circle at 50% -10%,rgba(229,9,20,.08),transparent 32%),
    #000000;
}
.player-responsive{
  box-shadow:0 20px 70px rgba(0,0,0,.55);
}
.back-btn{
  width:46px;height:46px;
  display:grid;
  place-items:center;
  border-radius:50%;
  background:rgba(0,0,0,.55);
  backdrop-filter:blur(8px);
  font-size:28px;
}
.modal-info{
  padding:36px clamp(4%,4vw,7%) 50px;
  gap:50px;
}
.media-description{
  padding:4px 0;
}
.cover-wrap{
  position:sticky;
  top:95px;
}
.cover-image{
  border-radius:12px;
  border:1px solid rgba(255,255,255,.1);
  box-shadow:0 25px 60px rgba(0,0,0,.6);
}
.platform-section{
  margin-top:0px;
  padding-top:0px;
  border-top:1px solid rgba(255,255,255,.1);
}
.platform-btn{
  border-radius:9px;
  background:#151515;
  border-color:#303030;
}
.platform-btn:hover{
  background:#222;
  border-color:#666;
  box-shadow:0 8px 25px rgba(0,0,0,.25);
}
.platform-btn.youtube{
  background:#e50914;
  border-color:#e50914;
}

/* Episodes */
.season-tabs{
  border-bottom-color:rgba(255,255,255,.1);
}
.tab-btn.active{
  color:#fff;
  border-bottom-color:var(--og-red);
}
.ep-row{
  padding:14px;
  border:1px solid transparent;
  margin-bottom:5px;
}
.ep-row:hover{
  background:#141414;
  border-color:rgba(255,255,255,.06);
}
.ep-thumb-wrap{
  border-radius:8px;
  box-shadow:0 7px 22px rgba(0,0,0,.3);
}

/* You may like */
.you-may-like{
  padding:0 clamp(3%,4vw,6%);
}
.you-may-like-card{
  border:1px solid rgba(255,255,255,.06);
}
.you-may-like-card:hover{
  border-color:rgba(255,255,255,.16);
}

/* Search */
.search-grid{
  max-width:1800px;
  margin:0 auto;
  display:flex;
  flex-wrap:nowrap;
  gap:16px;
  overflow-x:auto;
  overflow-y:hidden;
  padding:0 4px;
  scroll-behavior:smooth;
  scroll-snap-type:x proximity;
  -webkit-overflow-scrolling:touch;
  scrollbar-width:none;
  cursor:grab;
}
.search-grid:active{cursor:grabbing}
.search-grid::-webkit-scrollbar{display:none}
.search-grid .row-poster{
  flex:0 0 180px;
  width:180px;
  height:270px;
  scroll-snap-align:start;
}
.search-grid .row-poster img{
  width:100%;
  height:100%;
  object-fit:cover;
  display:block;
  border-radius:10px;
  transition:transform .25s ease,filter .25s ease;
}
.search-grid .row-poster:hover img{transform:scale(1.04);filter:brightness(1.08)}

/* Footer */
.site-footer{
  max-width:none;
  margin-top:80px;
  padding:55px clamp(6%,10vw,14%) 70px;
  border-top:1px solid rgba(255,255,255,.08);
  background:linear-gradient(180deg,#000000,#000000);
}
.footer-links a{transition:.2s;color:#777}
.footer-links a:hover{color:#fff;text-decoration:none}

/* Mobile */
@media(max-width:768px){
  .nav{height:62px}
  .header-widget img{max-height:35px}
  .banner{
    height:72vh;
    min-height:300px;
    background-position:center;
  }
  .banner-contents{
    margin-left:5%;
    margin-right:5%;
    margin-top:0;
    padding-top:500px;
  }
  .banner-title{
    font-size:clamp(30px,10vw,50px)!important;
  }
  .banner-desc{display:-webkit-box!important;font-size:13px;line-height:1.45}
  .btn{padding:.72rem 1.05rem;font-size:.9rem}
  .homepage-intro-inner{padding:0px 0px}
  .row{margin:7px 0}
  .featured-banner-section{
    margin:40px 3% 30px;
  }
  .featured-banner-slide{height:440px}
  .featured-banner-content{left:22px;right:22px;bottom:45px}
  .featured-banner-title{font-size:26px}
  .featured-banner-description{font-size:13px}
  #bossed-up-tv-section{margin:42px 3%}
  .bossed-up-tv-bezel{min-height:260px}
  .bossed-up-tv-screen{height:260px}
  .bossed-up-panel{padding:20px}
  .bossed-up-channels{grid-template-columns:1fr 1fr}
  .modal-info{
    grid-template-columns:1fr;
    padding:26px 5% 45px;
    gap:25px;
  }
  .cover-wrap{
    order:-1;
    position:relative;
    top:auto;
    max-width:360px;
    margin:0 auto;
  }
  .footer-links{grid-template-columns:repeat(2,1fr)}
}
@media(max-width:430px){
  .banner{
    min-height:700px;
    height:68vh;
  }
  .banner-contents{
    margin-left:5%;
    margin-right:5%;
    margin-top:0;
    padding-top:300px;
  }

  .banner-contents img{
    padding-top:100px;
  }

  .banner-btns{margin-top:1rem}
  .btn{padding:.68rem .85rem}
  .featured-banner-arrow{width:34px;height:50px}
  .bossed-up-channels{grid-template-columns:1fr}
  .footer-links{grid-template-columns:1fr 1fr}
}

/* Reduced-motion accessibility */
@media(prefers-reduced-motion:reduce){
  *,*:before,*:after{
    scroll-behavior:auto!important;
    transition-duration:.01ms!important;
    animation-duration:.01ms!important;
  }
}


    /* === CHANNEL SELECTOR === */
    .og-channel-selector { position: relative; display: inline-flex; align-items: center; z-index: 1000; }
    .og-channel-button { display: inline-flex; align-items: center; gap: 8px; background: transparent; border: 0; color: #fff; padding: 6px 4px; margin: 0; font: inherit; cursor: pointer; }
    .og-channel-button:hover { color: #ddd; }
    .og-top-right-icon{display:block!important;width:40px!important;height:40px!important;min-width:40px!important;min-height:40px!important;max-width:40px!important;max-height:40px!important;aspect-ratio:1/1!important;object-fit:cover!important;object-position:center!important;border-radius:8px!important;flex:0 0 40px!important;}
    .og-channel-button{min-width:48px;min-height:48px;justify-content:center;}
    .og-channel-button i { transition: transform .2s ease; }
    .og-channel-selector.open .og-channel-button i { transform: rotate(180deg); }
    /* JOIN dropdown */
    .join-selector{position:relative;margin-left:4px}
    .join-button{display:inline-flex;align-items:center;gap:4px;border:1px solid rgba(255,255,255,.14);background:#0b0b0b;color:#fff;border-radius:6px;padding:7px 9px;font-size:11px;font-weight:900;letter-spacing:.08em;cursor:pointer}
    .join-button:hover{background:#181818;border-color:rgba(255,255,255,.3)}
    .join-dropdown{display:none;position:absolute;top:calc(100% + 10px);right:0;min-width:185px;padding:8px;background:rgba(12,12,12,.98);border:1px solid rgba(255,255,255,.16);border-radius:8px;box-shadow:0 14px 35px rgba(0,0,0,.65);z-index:100000}
    .join-selector.open .join-dropdown{display:flex;flex-direction:column}
    .join-option{display:flex;align-items:center;justify-content:space-between;width:100%;box-sizing:border-box;color:#fff!important;text-decoration:none!important;background:transparent;border:0;padding:10px 12px;border-radius:5px;font-size:12px;line-height:1.2;text-align:left;cursor:pointer}
    .join-option span{color:#888;margin-left:8px}
    .join-option:hover{background:rgba(255,255,255,.09);color:#fff!important}
    @media(max-width:640px){.og-top-right-icon{width:36px!important;height:36px!important;min-width:36px!important;min-height:36px!important;max-width:36px!important;max-height:36px!important;flex-basis:36px!important}.og-channel-button{min-width:42px;min-height:42px}.join-button{padding:6px 7px;font-size:10px}.join-dropdown{right:-4px;min-width:170px}}

    .og-channel-dropdown { display: none; position: absolute; top: calc(100% + 10px); right: 0; min-width: 190px; padding: 8px; background: rgba(12,12,12,.98); border: 1px solid rgba(255,255,255,.16); border-radius: 8px; box-shadow: 0 14px 35px rgba(0,0,0,.65); z-index: 99999; }
    .og-channel-selector.open .og-channel-dropdown { display: flex; flex-direction: column; }
    .og-channel-option { display: block; color: #fff !important; text-decoration: none !important; padding: 10px 12px; border-radius: 5px; font-size: 13px; line-height: 1.2; white-space: nowrap; background: transparent; }
    .og-channel-option:hover { background: rgba(255,0,0,.18); color: #fff !important; }
    .og-channel-selector-inside { margin-left: 4px; }
    @media (max-width: 640px) { .og-channel-dropdown { right: -10px; min-width: 175px; } .og-channel-option { font-size: 12px; } }


    /* =========================================================
       MIXCLOUD EMBEDS - ALLOWED SITEWIDE
       Mixcloud supplies iframe widgets for shows, tracks and playlists.
    ========================================================= */
    /* =========================================================
       MIXCLOUD EMBEDS - SITEWIDE SUPPORT
       Supports official Mixcloud iframe widgets in Blogger posts,
       static pages, homepage sections, widgets and dynamic content.
    ========================================================= */
    .ogflix-mixcloud-wrap{
      display:block;
      width:100%;
      max-width:100%;
      margin:18px 0;
      overflow:hidden;
      border-radius:12px;
      background:#111;
    }
    .ogflix-mixcloud-embed,
    iframe[src*="mixcloud.com"],
    iframe[src*="player-widget.mixcloud.com"]{
      display:block !important;
      width:100% !important;
      max-width:100% !important;
      min-width:0 !important;
      min-height:180px;
      height:auto;
      border:0 !important;
      border-radius:12px;
      overflow:hidden;
      background:#111;
      margin:0 !important;
      box-sizing:border-box;
    }
    .post-body iframe[src*="mixcloud.com"],
    .entry-content iframe[src*="mixcloud.com"],
    .ogflix-page-body iframe[src*="mixcloud.com"],
    #post-body-raw iframe[src*="mixcloud.com"],
    #main-view iframe[src*="mixcloud.com"],
    .widget iframe[src*="mixcloud.com"]{
      min-height:180px;
    }
    @media(max-width:768px){
      .ogflix-mixcloud-wrap,
      .ogflix-mixcloud-embed,
      .post-body iframe[src*="mixcloud.com"],
      .entry-content iframe[src*="mixcloud.com"],
      .ogflix-page-body iframe[src*="mixcloud.com"],
      #post-body-raw iframe[src*="mixcloud.com"]{
        width:100% !important;
        max-width:100% !important;
        min-height:160px;
        border-radius:10px;
      }
    }

    /* === OGFLIX RESPONSIVE FIT / NO HORIZONTAL OVERFLOW === */
    html,body{width:100%;max-width:100%;overflow-x:hidden}
    *,*:before,*:after{box-sizing:border-box}
    img,svg,video,iframe{max-width:100%}
    #main-view,.main-posts,.blog-posts,.page-body,.content-wrapper{width:100%;max-width:1800;min-width:0}
    .nav{width:100%;max-width:100vw;min-width:0}
    .nav>div{min-width:0}
    .header-section,.header-widget{min-width:0}
    .menu-section,.menu-widget,.menu-widget ul{min-width:0}
    .search-box{width:100%;max-width:100vw;min-width:0}
    .search-box input{min-width:0}
    .row,.featured-banner-section,#bossed-up-tv-section,.homepage-intro{max-width:100%;min-width:0}
    .row-posters{max-width:100%;min-width:0;overflow-x:auto}
    .featured-banner-section{overflow:hidden}
    .featured-banner-track{width:100%;min-width:0}
    .featured-banner-slide{min-width:100%;max-width:100vw}
    .bossed-up-tv-wrap{width:100%;min-width:0;grid-template-columns:minmax(0,1.9fr) minmax(0,1fr)}
    .bossed-up-tv-frame,.bossed-up-panel,.bossed-up-tv-bezel{min-width:0;max-width:100%}
    .bossed-up-tv-screen,.bossed-up-tv-playlist{width:100%;max-width:100%;display:block}
    .bossed-up-channels{min-width:0}
    .bossed-up-channel{min-width:0;max-width:100%;overflow:hidden}
    .bossed-up-channel-name{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}

    @media (max-width:1100px){
      .nav{padding-left:24px;padding-right:24px}
      .menu-widget ul{gap:16px}
      .bossed-up-tv-wrap{grid-template-columns:minmax(0,1.55fr) minmax(240px,1fr);gap:18px}
      .bossed-up-tv-screen,.bossed-up-tv-playlist{height:380px}
    }
    @media (max-width:900px){
      .nav{padding-left:18px;padding-right:18px}
      .bossed-up-tv-wrap{grid-template-columns:1fr}
      .bossed-up-tv-screen,.bossed-up-tv-playlist{height:360px}
      .bossed-up-panel{width:100%}
    }
    @media (max-width:768px){
      .nav{height:62px;padding-left:14px;padding-right:14px}
      .header-widget img{max-height:34px}
      .nav .flex.items-center.gap-6{gap:10px!important}
      .nav .bx-search{font-size:1.25rem!important}
      .og-channel-button{max-width:150px;overflow:hidden}
      .og-channel-button span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
      #bossed-up-tv-section{margin:34px 3%}
      .bossed-up-tv-frame{padding:8px;border-radius:16px}
      .bossed-up-tv-bezel{border-radius:10px}
      .bossed-up-tv-screen,.bossed-up-tv-playlist{height:auto;aspect-ratio:16/9;min-height:0}
      .bossed-up-tv-empty,.bossed-up-tv-preview{min-height:0;height:auto;aspect-ratio:16/9}
      .bossed-up-panel{padding:18px;border-radius:16px}
      .bossed-up-channels{grid-template-columns:repeat(2,minmax(0,1fr))}
    }
    @media (max-width:520px){
      .nav{padding-left:6px;padding-right:6px;overflow:visible}
      .nav > .flex.items-center.w-full{width:100%;max-width:100%;min-width:0}
      .nav .header-section{max-width:38vw;min-width:0;overflow:hidden;flex:0 1 auto}
      .header-widget{min-width:0;max-width:100%}
      .header-widget h1{font-size:20px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
      .header-widget img{max-width:118px;height:auto}
      .nav .flex.items-center.gap-6{gap:5px!important;margin-left:auto!important;min-width:0;max-width:58vw;flex:0 1 auto;transform:translateX(-3px)}
      .nav .flex.items-center.gap-2{gap:3px!important;min-width:0}
      .nav .bx-search{font-size:1.12rem!important;flex:0 0 auto;margin:0!important}
      .og-channel-selector-inside{margin-left:0!important;flex:0 0 auto}
      .og-top-right-icon{width:32px!important;height:32px!important;min-width:32px!important;min-height:32px!important;max-width:32px!important;max-height:32px!important}
      .og-channel-button{padding:3px 1px;gap:2px;min-width:36px;max-width:36px;width:36px;height:36px;font-size:10px}
      .og-channel-button span{display:none}
      .og-channel-dropdown{right:-4px;min-width:165px;max-width:calc(100vw - 12px)}
      .og-channel-option{padding:9px;font-size:11px}
      .join-selector{margin-left:0!important;flex:0 0 auto}
      .join-button{padding:5px 6px;font-size:9px;gap:2px;white-space:nowrap}
      .join-dropdown{right:-2px;min-width:160px;max-width:calc(100vw - 12px)}
      .bossed-up-tv-wrap{gap:14px}
      .bossed-up-channels{grid-template-columns:1fr}
      .bossed-up-title{font-size:30px}
      .homepage-intro-inner{padding:22px 18px}
      .row{padding-left:0;margin-left:3%;margin-right:3%}
      .featured-banner-section{margin-left:3%;margin-right:3%}
    }
    @media (max-width:360px){
      .nav{padding-left:4px;padding-right:4px}
      .nav .header-section{max-width:34vw}
      .header-widget h1{font-size:17px}
      .header-widget img{max-width:105px}
      .nav .flex.items-center.gap-6{gap:4px!important;max-width:64vw;transform:translateX(-5px)}
      .nav .bx-search{display:block;font-size:1rem!important}
      .og-top-right-icon{width:29px!important;height:29px!important;min-width:29px!important;min-height:29px!important;max-width:29px!important;max-height:29px!important}
      .og-channel-button{min-width:32px;max-width:32px;width:32px;height:32px;padding:2px}
      .join-button{padding:4px 5px;font-size:8px}
    }


    /* === BOSSED UP TV: PREVIOUS PREMIUM STYLE + RESPONSIVE CONTAINMENT === */
    #bossed-up-tv-section{
      width:min(1180px,calc(100% - 48px));
      max-width:1180px;
      margin:60px auto !important;
      padding:0 !important;
      min-width:0;
      overflow:hidden;
    }
    #bossed-up-tv-section .bossed-up-tv-wrap{
      width:100%;
      max-width:1180px;
      min-width:0;
      display:grid;
      grid-template-columns:minmax(0,1.9fr) minmax(260px,1fr);
      gap:8px;
      align-items:stretch;
    }
    #bossed-up-tv-section .bossed-up-tv-frame,
    #bossed-up-tv-section .bossed-up-panel,
    #bossed-up-tv-section .bossed-up-tv-bezel{
      width:100%;
      max-width:100%;
      min-width:0;
    }
    #bossed-up-tv-section .bossed-up-tv-frame{
      position:relative;
      padding:12px;
      border:1px solid #000000;
      border-radius:22px;
      background:linear-gradient(145deg,#000000,#000000);
      box-shadow:0 25px 70px rgba(0,0,0,.6);
      overflow:hidden;
    }
    #bossed-up-tv-section .bossed-up-tv-bezel{
      min-height:0;
      aspect-ratio:16/9;
      border-radius:14px;
      background:#000;
      overflow:hidden;
      box-shadow:inset 0 0 60px #000;
    }
    #bossed-up-tv-section .bossed-up-tv-playlist,
    #bossed-up-tv-section .bossed-up-tv-screen{
      display:block;
      width:100%;
      max-width:100%;
      height:100%;
      min-height:0;
      border:0;
      background:#000;
    }
    #bossed-up-tv-section .bossed-up-tv-controls{
      margin-top:12px;
    }
    #bossed-up-tv-section .bossed-up-panel{
      min-height:0;
      padding:24px;
      border-radius:22px;
      border:1px solid rgba(255,255,255,.1);
      background:
        radial-gradient(circle at 100% 0%,rgba(229,9,20,.12),transparent 35%),
        linear-gradient(145deg,#000000,#000000);
      box-shadow:0 25px 70px rgba(0,0,0,.45);
      overflow:hidden;
    }
    #bossed-up-tv-section .bossed-up-kicker{
      color:#e50914;
      font-weight:900;
      letter-spacing:2.5px;
    }
    #bossed-up-tv-section .bossed-up-title{
      font-size:clamp(30px,3vw,46px);
      letter-spacing:-.045em;
      margin:0 0 8px;
    }
    #bossed-up-tv-section .bossed-up-copy{
      color:#aaa;
      line-height:1.5;
    }
    #bossed-up-tv-section .bossed-up-channels{
      width:100%;
      min-width:0;
      grid-template-columns:repeat(2,minmax(0,1fr));
      gap:10px;
      overflow:auto;
    }
    #bossed-up-tv-section .bossed-up-channel{
      min-width:0;
      width:100%;
      padding:12px;
      border:1px solid #3a3a3a;
      border-radius:10px;
      background:#111;
      transition:.2s ease;
      overflow:hidden;
    }
    #bossed-up-tv-section .bossed-up-channel:hover{
      transform:translateY(-2px);
      border-color:#666;
      background:#1d1d1d;
    }
    #bossed-up-tv-section .bossed-up-channel.active{
      border-color:#e50914;
      background:#191919;
      box-shadow:0 0 0 1px rgba(229,9,20,.2),0 10px 25px rgba(0,0,0,.25);
    }
    #bossed-up-tv-section .bossed-up-channel-number{
      font-size:9px;
      color:#777;
      letter-spacing:1.5px;
    }
    #bossed-up-tv-section .bossed-up-channel-name{
      display:block;
      margin-top:3px;
      font-size:14px;
      font-weight:900;
      min-width:0;
      overflow:hidden;
      text-overflow:ellipsis;
      white-space:nowrap;
    }
    #bossed-up-tv-section .bossed-up-now{
      margin-top:18px;
      border-top:1px solid #000;
      padding-top:15px;
      color:#bbb;
      font-size:13px;
    }
    #bossed-up-tv-section .bossed-up-now strong{color:#fff}

    @media(max-width:900px){
      #bossed-up-tv-section{width:min(100%,calc(100% - 28px));margin:46px auto !important;}
      #bossed-up-tv-section .bossed-up-tv-wrap{grid-template-columns:1fr;gap:22px;}
      #bossed-up-tv-section .bossed-up-tv-bezel{aspect-ratio:16/9;}
      #bossed-up-tv-section .bossed-up-tv-playlist,
      #bossed-up-tv-section .bossed-up-tv-screen{height:100%;}
    }
    @media(max-width:520px){
      #bossed-up-tv-section{width:calc(100% - 16px);margin:34px auto !important;}
      #bossed-up-tv-section .bossed-up-tv-wrap{gap:14px;}
      #bossed-up-tv-section .bossed-up-tv-frame{padding:8px;border-radius:16px;}
      #bossed-up-tv-section .bossed-up-tv-bezel{border-radius:10px;}
      #bossed-up-tv-section .bossed-up-panel{padding:18px;border-radius:16px;}
      #bossed-up-tv-section .bossed-up-channels{grid-template-columns:1fr 1fr;}
    }
    @media(max-width:380px){
      #bossed-up-tv-section .bossed-up-channels{grid-template-columns:1fr;}
    }

    /* === FEATURED MOVIE DIRECTOR === */
    .featured-director-section{
      width:min(1500px,calc(100% - clamp(24px,8vw,116px)));
      margin:42px auto 54px;
      padding:28px;
      box-sizing:border-box;
      border:1px solid rgba(255,255,255,.10);
      border-radius:18px;
      background:linear-gradient(145deg,#080808,#000);
      box-shadow:0 24px 70px rgba(0,0,0,.55);
    }
    .featured-director-heading{
      display:flex;align-items:end;justify-content:space-between;gap:20px;
      margin:0 0 20px;
    }
    .featured-director-kicker{
      color:#e50914;font-size:11px;font-weight:900;letter-spacing:.14em;text-transform:uppercase;margin-bottom:6px;
    }
    .featured-director-heading h2{
      margin:0;color:#fff;font-size:clamp(22px,2.4vw,34px);font-weight:900;letter-spacing:-.03em;
    }
    .featured-director-layout{
      display:grid;grid-template-columns:minmax(320px,500px) minmax(0,1fr);gap:34px;align-items:start;
    }
    .featured-director-image{
      width:500px;max-width:100%;height:500px;object-fit:cover;display:block;
      border-radius:14px;background:#111;border:1px solid rgba(255,255,255,.08);
      box-shadow:0 18px 55px rgba(0,0,0,.55);
    }
    .featured-director-copy{min-width:0}
    .featured-director-name{
      margin:4px 0 12px;color:#fff;font-size:clamp(26px,3vw,44px);font-weight:900;line-height:1.05;
    }
    .featured-director-role{
      color:#e50914;font-size:12px;font-weight:900;text-transform:uppercase;letter-spacing:.12em;margin-bottom:16px;
    }
    .featured-director-bio{
      height:330px;overflow-y:auto;padding:4px 20px 8px 0;color:#bcbcbc;font-size:15px;line-height:1.8;
      scrollbar-width:thin;scrollbar-color:#555 transparent;
    }
    .featured-director-bio::-webkit-scrollbar{width:7px}
    .featured-director-bio::-webkit-scrollbar-track{background:transparent}
    .featured-director-bio::-webkit-scrollbar-thumb{background:#555;border-radius:20px}
    .featured-director-socials{display:flex;flex-wrap:wrap;gap:9px;margin-top:20px}
    .featured-director-social{
      display:inline-flex;align-items:center;gap:8px;padding:11px 15px;border-radius:7px;
      border:1px solid rgba(255,255,255,.12);background:#111;color:#fff;text-decoration:none;font-size:12px;font-weight:900;
      transition:.2s ease;
    }
    .featured-director-social:hover{background:#e50914;border-color:#e50914;transform:translateY(-2px)}
    @media(max-width:900px){
      .featured-director-section{width:calc(100% - 24px);padding:20px;margin:34px auto 44px}
      .featured-director-layout{grid-template-columns:1fr;gap:22px}
      .featured-director-image{width:min(500px,100%);height:auto;aspect-ratio:1/1;margin:0 auto}
      .featured-director-bio{height:260px}
    }
    @media(max-width:520px){
      .featured-director-section{padding:16px;border-radius:14px}
      .featured-director-social{flex:1 1 calc(50% - 9px);justify-content:center}
    }




/* =========================================================
   OGFLIX MOBILE POST VIDEO — SAFE SPACE BELOW FIXED HEADER
   Post pages only. Keeps the complete video canvas visible.
   Homepage spacing is not affected.
   ========================================================= */
@media screen and (max-width:768px){
  /* Move the entire post player below the fixed mobile header.
     Do NOT add margin to the iframe itself, because that crops
     the top of the 16:9 YouTube canvas. */
  .modal-overlay.active{
    padding-top:78px !important;
    box-sizing:border-box !important;
  }

  .modal-overlay.active .player-responsive{
    margin-top:0 !important;
  }

  .modal-overlay.active .player-responsive iframe,
  .modal-overlay.active .player-responsive video{
    top:0 !important;
    height:100% !important;
  }

  /* Smaller movie/music cover on mobile only. */
  .modal-overlay.active .cover-wrap{
    width:100% !important;
    max-width:205px !important;
    margin-left:auto !important;
    margin-right:auto !important;
  }

  .modal-overlay.active .cover-image{
    width:100% !important;
    max-width:205px !important;
    height:auto !important;
    aspect-ratio:2/3 !important;
  }

  .post-body.entry-content iframe{
    max-width:100% !important;
  }
}

@media screen and (max-width:430px){
  .modal-overlay.active .cover-wrap,
  .modal-overlay.active .cover-image{
    max-width:180px !important;
  }
}

/* =========================================================
   OGFLIX MOBILE HEADER — HARD RESET MENU / LOGO SPACING
   Fixes Blogger Header widget flex sizing that can create a
   visible gap between the hamburger menu and header image.
   ========================================================= */
@media (max-width:768px){
  #nav{
    padding-left:0 !important;
    padding-right:4px !important;
  }

  #nav > .flex.items-center.w-full{
    display:flex !important;
    align-items:center !important;
    justify-content:flex-start !important;
    gap:0 !important;
    column-gap:0 !important;
    margin:0 !important;
    padding:0 !important;
    width:100% !important;
    min-width:0 !important;
  }

  /* Hamburger: fixed footprint, no hidden spacing. */
  #nav > .flex.items-center.w-full > .bx-menu{
    display:block !important;
    flex:0 0 30px !important;
    width:30px !important;
    min-width:30px !important;
    max-width:30px !important;
    height:32px !important;
    line-height:32px !important;
    margin:0 !important;
    padding:0 !important;
    position:relative !important;
    left:0 !important;
  }

  /* Blogger b:section itself must shrink to the actual logo. */
  #nav > .flex.items-center.w-full > .header-section,
  #nav > .flex.items-center.w-full > #header{
    display:flex !important;
    align-items:center !important;
    flex:0 0 auto !important;
    flex-basis:auto !important;
    width:auto !important;
    min-width:0 !important;
    max-width:none !important;
    margin:0 !important;
    padding:0 !important;
  }

  /* Remove spacing Blogger may add to the generated widget. */
  #nav .header-section > .widget,
  #nav .header-section .widget,
  #nav .header-section .widget-content,
  #nav .header-widget,
  #nav .header-image-wrapper{
    display:block !important;
    width:auto !important;
    min-width:0 !important;
    max-width:none !important;
    margin:0 !important;
    padding:0 !important;
  }

  #nav .header-widget img,
  #nav .header-image-wrapper img{
    display:block !important;
    width:auto !important;
    height:auto !important;
    max-width:118px !important;
    max-height:40px !important;
    margin:0 !important;
    padding:0 !important;
  }

  /* Keep right-side controls pushed to the right without affecting logo. */
  #nav > .flex.items-center.w-full > .flex.items-center.gap-6{
    margin-left:auto !important;
    padding:0 !important;
  }
}

@media (max-width:520px){
  #nav{
    padding-left:0 !important;
    padding-right:3px !important;
  }

  #nav > .flex.items-center.w-full > .bx-menu{
    flex-basis:28px !important;
    width:28px !important;
    min-width:28px !important;
    max-width:28px !important;
    font-size:1.75rem !important;
  }

  #nav .header-widget img,
  #nav .header-image-wrapper img{
    max-width:118px !important;
    max-height:38px !important;
  }
}

@media (max-width:360px){
  #nav > .flex.items-center.w-full > .bx-menu{
    flex-basis:26px !important;
    width:26px !important;
    min-width:26px !important;
    max-width:26px !important;
    font-size:1.65rem !important;
  }

  #nav .header-widget img,
  #nav .header-image-wrapper img{
    max-width:105px !important;
    max-height:34px !important;
  }
}



/* =========================================================
   OGFLIX — HOMEPAGE MOBILE SPACING ONLY
   Remove the extra space between the mobile header and the
   homepage Trending/hero area WITHOUT changing post pages.
   ========================================================= */

@media screen and (max-width:768px){
  /* Only applies when the homepage banner exists. */
  body:has(#banner),
  body:has(#banner) #app-root,
  body:has(#banner) #main-view,
  body:has(#banner) #main-view .main-posts,
  body:has(#banner) #main-view #Blog1,
  body:has(#banner) #main-view #Blog1 .widget-content{
    margin-top:0 !important;
    padding-top:0 !important;
  }

  /* The mobile homepage is currently carrying an extra vertical block
     above the hero. Pull ONLY the homepage main view up so the hero
     starts directly beneath the fixed 62px header. Post pages are untouched. */
  body:has(#banner) #main-view{
    position:relative !important;
    top:-160px !important;
    margin-bottom:-160px !important;
  }

  /* The homepage banner is the first visible content.
     Do not alter post/article media containers. */
  body:has(#banner) #main-view .banner{
    display:block !important;
    position:relative !important;
    top:0 !important;
    margin-top:0 !important;
    padding-top:0 !important;
  }

  /* Fixed header overlays the homepage instead of reserving space. */
  body:has(#banner) #nav{
    position:fixed !important;
    top:0 !important;
    left:0 !important;
    right:0 !important;
  }
}

/* Keep post pages completely independent from the homepage spacing fix. */
@media screen and (min-width:769px){
  body:has(#banner) #main-view .banner{
    margin-top:0 !important;
  }
}



\n/* =========================================================\n   OGFLIX MOBILE HEADER CONTROLS — NO OVERLAP\n   Keeps Search + Channel + JOIN inside the nav and spaced\n   safely away from the logo on mobile.\n   ========================================================= */\n@media screen and (max-width:768px){\n  #nav{\n    position:relative !important;\n    width:100% !important;\n    overflow:visible !important;\n  }\n\n  #ogHeaderControls{\n    display:flex !important;\n    align-items:center !important;\n    justify-content:flex-end !important;\n    flex:0 0 auto !important;\n    width:auto !important;\n    min-width:0 !important;\n    margin-left:auto !important;\n    padding:0 !important;\n    gap:6px !important;\n    white-space:nowrap !important;\n    position:relative !important;\n    z-index:20 !important;\n  }\n\n  #ogHeaderControls > .bx-search{\n    flex:0 0 30px !important;\n    width:30px !important;\n    min-width:30px !important;\n    max-width:30px !important;\n    margin:0 !important;\n    padding:0 !important;\n    text-align:center !important;\n  }\n\n  #ogHeaderControls .og-channel-selector-inside{\n    flex:0 0 auto !important;\n    margin:0 !important;\n  }\n\n  #ogHeaderControls .og-channel-button{\n    display:flex !important;\n    align-items:center !important;\n    justify-content:center !important;\n    min-width:44px !important;\n    width:44px !important;\n    max-width:44px !important;\n    min-height:42px !important;\n    padding:2px !important;\n    margin:0 !important;\n    overflow:hidden !important;\n  }\n\n  #ogHeaderControls .og-top-right-icon{\n    width:36px !important;\n    height:36px !important;\n    min-width:36px !important;\n    min-height:36px !important;\n    max-width:36px !important;\n    max-height:36px !important;\n    object-fit:contain !important;\n    margin:0 !important;\n  }\n\n  #ogHeaderControls .join-selector{\n    flex:0 0 auto !important;\n    margin:0 !important;\n  }\n\n  #ogHeaderControls .join-button{\n    min-width:54px !important;\n    width:54px !important;\n    max-width:54px !important;\n    padding:7px 5px !important;\n    margin:0 !important;\n    white-space:nowrap !important;\n  }\n}\n\n@media screen and (max-width:430px){\n  #nav > .flex.items-center.w-full{\n    padding-right:2px !important;\n  }\n\n  #nav .header-widget img,\n  #nav .header-image-wrapper img{\n    max-width:112px !important;\n    max-height:38px !important;\n  }\n\n  #ogHeaderControls{\n    gap:4px !important;\n  }\n\n  #ogHeaderControls > .bx-search{\n    flex-basis:28px !important;\n    width:28px !important;\n    min-width:28px !important;\n    max-width:28px !important;\n    font-size:25px !important;\n  }\n\n  #ogHeaderControls .og-channel-button{\n    width:42px !important;\n    min-width:42px !important;\n    max-width:42px !important;\n  }\n\n  #ogHeaderControls .og-top-right-icon{\n    width:34px !important;\n    height:34px !important;\n    min-width:34px !important;\n    min-height:34px !important;\n    max-width:34px !important;\n    max-height:34px !important;\n  }\n\n  #ogHeaderControls .join-button{\n    width:50px !important;\n    min-width:50px !important;\n    max-width:50px !important;\n    padding-left:3px !important;\n    padding-right:3px !important;\n    font-size:10px !important;\n  }\n}\n

/* =========================================================
   OGFLIX SEARCH / LABEL PAGES — FINAL LAYOUT FIX
   Keep results in their own full-width page area so they do
   not overlap the header, sponsor banner, or footer.
   ========================================================= */
#search-results-container:not(.hidden){
  display:block !important;
  position:relative !important;
  float:none !important;
  clear:both !important;
  width:100% !important;
  max-width:1800px !important;
  min-width:0 !important;
  margin:0 auto !important;
  padding:92px clamp(18px,4vw,58px) 50px !important;
  box-sizing:border-box !important;
  overflow:visible !important;
  z-index:2 !important;
}

#search-results-container:not(.hidden) .search-grid{
  display:grid !important;
  grid-template-columns:repeat(6,minmax(0,1fr)) !important;
  gap:18px !important;
  width:100% !important;
  max-width:1600px !important;
  margin:0 auto !important;
  padding:0 !important;
  overflow:visible !important;
  box-sizing:border-box !important;
  align-items:start !important;
}

#search-results-container:not(.hidden) .search-grid .row-poster{
  display:block !important;
  width:100% !important;
  height:auto !important;
  min-width:0 !important;
  aspect-ratio:2 / 3 !important;
  flex:none !important;
  margin:0 !important;
  overflow:hidden !important;
  border-radius:8px !important;
  cursor:pointer !important;
}

#search-results-container:not(.hidden) .search-grid .row-poster img{
  display:block !important;
  width:100% !important;
  height:100% !important;
  min-width:0 !important;
  min-height:0 !important;
  object-fit:cover !important;
  border-radius:8px !important;
}

