\n\n/* =========================================================\n   OGFLIX LABEL CATALOG — NATURAL VERTICAL SCROLL\n   Navigation stays at the top. The catalog owns its full height.\n   Footer comes only after every movie cover.\n   ========================================================= */\nhtml body.og-search-page{\n  overflow-x:hidden !important;\n  overflow-y:auto !important;\n}\n\nhtml body.og-search-page #search-results-container:not(.hidden){\n  position:relative !important;\n  display:block !important;\n  float:none !important;\n  clear:both !important;\n  width:100% !important;\n  max-width:none !important;\n  height:auto !important;\n  min-height:0 !important;\n  margin:0 !important;\n  padding:92px 24px 70px !important;\n  box-sizing:border-box !important;\n  overflow:visible !important;\n  z-index:1 !important;\n}\n\nhtml body.og-search-page #search-results-container:not(.hidden) > #search-grid.label-mode{\n  display:block !important;\n  position:relative !important;\n  width:100% !important;\n  max-width:1380px !important;\n  height:auto !important;\n  min-height:0 !important;\n  margin:0 auto !important;\n  padding:0 !important;\n  overflow:visible !important;\n}\n\nhtml body.og-search-page #search-results-container:not(.hidden) .label-page-shell{\n  display:block !important;\n  position:relative !important;\n  width:100% !important;\n  max-width:1380px !important;\n  height:auto !important;\n  min-height:0 !important;\n  margin:0 auto !important;\n  padding:0 !important;\n  overflow:visible !important;\n}\n\nhtml body.og-search-page #search-results-container:not(.hidden) .label-page-heading{\n  display:block !important;\n  position:relative !important;\n  margin:0 0 34px !important;\n  padding:0 !important;\n}\n\nhtml body.og-search-page #search-results-container:not(.hidden) .label-page-heading h1{\n  margin:0 !important;\n  line-height:1.1 !important;\n}\n\nhtml body.og-search-page #search-results-container:not(.hidden) .label-section{\n  display:block !important;\n  position:relative !important;\n  width:100% !important;\n  height:auto !important;\n  min-height:0 !important;\n  margin:0 0 48px !important;\n  padding:0 !important;\n  clear:both !important;\n  overflow:visible !important;\n}\n\n/* Top 10 / New Releases remain horizontally scrollable rows. */\nhtml body.og-search-page #search-results-container:not(.hidden) .label-horizontal{\n  display:flex !important;\n  position:relative !important;\n  width:100% !important;\n  height:auto !important;\n  min-height:0 !important;\n  margin:0 !important;\n  padding:8px 4px 22px !important;\n  gap:16px !important;\n  overflow-x:auto !important;\n  overflow-y:hidden !important;\n  box-sizing:border-box !important;\n  align-items:flex-start !important;\n  flex-wrap:nowrap !important;\n}\n\nhtml body.og-search-page #search-results-container:not(.hidden) .label-horizontal .label-card{\n  flex:0 0 180px !important;\n  width:180px !important;\n  min-width:180px !important;\n  max-width:180px !important;\n  height:270px !important;\n  position:relative !important;\n  margin:0 !important;\n  transform:none !important;\n  float:none !important;\n}\n\n/* ALL VIDEOS = the main catalog. Cards wrap into real rows, so the browser\n   page itself grows and the viewer simply scrolls down to choose a movie. */\nhtml body.og-search-page #search-results-container:not(.hidden) .label-all-grid{\n  display:grid !important;\n  position:relative !important;\n  width:100% !important;\n  max-width:1380px !important;\n  height:auto !important;\n  min-height:0 !important;\n  margin:0 auto !important;\n  padding:8px 0 40px !important;\n  box-sizing:border-box !important;\n  grid-template-columns:repeat(6,minmax(0,1fr)) !important;\n  grid-auto-rows:auto !important;\n  gap:22px 18px !important;\n  align-items:start !important;\n  align-content:start !important;\n  overflow:visible !important;\n  clear:both !important;\n}\n\nhtml body.og-search-page #search-results-container:not(.hidden) .label-all-grid .label-card{\n  display:block !important;\n  position:relative !important;\n  width:100% !important;\n  min-width:0 !important;\n  max-width:none !important;\n  height:auto !important;\n  aspect-ratio:2 / 3 !important;\n  margin:0 !important;\n  padding:0 !important;\n  transform:none !important;\n  float:none !important;\n  overflow:hidden !important;\n  box-sizing:border-box !important;\n  align-self:start !important;\n}\n\nhtml body.og-search-page #search-results-container:not(.hidden) .label-all-grid .label-card img{\n  display:block !important;\n  position:absolute !important;\n  inset:0 !important;\n  width:100% !important;\n  height:100% !important;\n  max-width:none !important;\n  min-width:0 !important;\n  margin:0 !important;\n  padding:0 !important;\n  object-fit:cover !important;\n}\n\n/* Footer is physically after the catalog and cannot occupy its grid space. */\nhtml body.og-search-page .site-footer{\n  display:block !important;\n  position:relative !important;\n  float:none !important;\n  clear:both !important;\n  width:100% !important;\n  max-width:none !important;\n  height:auto !important;\n  min-height:0 !important;\n  margin:0 !important;\n  padding:55px clamp(24px,8vw,140px) 125px !important;\n  box-sizing:border-box !important;\n  z-index:5 !important;\n}\n\n/* The radio player stays fixed at the bottom, but never changes catalog flow. */\nhtml body.og-search-page #promoBar{\n  position:fixed !important;\n  left:0 !important;\n  right:0 !important;\n  bottom:0 !important;\n  z-index:1500 !important;\n}\n\n@media(max-width:1100px){\n  html body.og-search-page #search-results-container:not(.hidden) .label-all-grid{\n    grid-template-columns:repeat(5,minmax(0,1fr)) !important;\n  }\n}\n\n@media(max-width:900px){\n  html body.og-search-page #search-results-container:not(.hidden){\n    padding:82px 18px 60px !important;\n  }\n  html body.og-search-page #search-results-container:not(.hidden) .label-all-grid{\n    grid-template-columns:repeat(4,minmax(0,1fr)) !important;\n    gap:18px 14px !important;\n  }\n}\n\n@media(max-width:768px){\n  html body.og-search-page #search-results-container:not(.hidden){\n    padding:72px 10px 55px !important;\n  }\n  html body.og-search-page #search-results-container:not(.hidden) .label-horizontal{\n    gap:12px !important;\n  }\n  html body.og-search-page #search-results-container:not(.hidden) .label-horizontal .label-card{\n    flex-basis:145px !important;\n    width:145px !important;\n    min-width:145px !important;\n    max-width:145px !important;\n    height:218px !important;\n  }\n  html body.og-search-page #search-results-container:not(.hidden) .label-all-grid{\n    grid-template-columns:repeat(3,minmax(0,1fr)) !important;\n    gap:14px 9px !important;\n    padding-bottom:30px !important;\n  }\n  html body.og-search-page .site-footer{\n    padding:45px 18px 105px !important;\n  }\n}\n\n@media(max-width:480px){\n  html body.og-search-page #search-results-container:not(.hidden){\n    padding:68px 8px 45px !important;\n  }\n  html body.og-search-page #search-results-container:not(.hidden) .label-all-grid{\n    grid-template-columns:repeat(2,minmax(0,1fr)) !important;\n    gap:14px 10px !important;\n  }\n}\n

td.script:
//
document.addEventListener('DOMContentLoaded', function () {
  var openBtn = document.getElementById('openModalBtn');
  var closeBtn = document.getElementById('closeModalBtn');
  var modal = document.getElementById('videoModal');
  var iframeContainer = document.getElementById('iframeContainer');

  var iframeHTML = "<iframe src='https://player.viloud.tv/embed/channel/8aa9ff07a8abeb26ad5982a05badb87c?autoplay=1&volume=1&controls=0&title=1&share=0&open_playlist=0&random=1' style='position: absolute; top: 0; left: 0; width: 100%; height: 100%; border: 0;' allow='autoplay; fullscreen' allowfullscreen='allowfullscreen'></iframe>";

  openBtn.addEventListener('click', function () {
    iframeContainer.innerHTML = iframeHTML;
    modal.classList.add('active');
  });

  function closeModal() {
    modal.classList.remove('active');
    iframeContainer.innerHTML = '';
  }

  closeBtn.addEventListener('click', closeModal);

  modal.addEventListener('click', function (e) {
    if (e.target === modal) {
      closeModal();
    }
  });

  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape' && modal.classList.contains('active')) {
      closeModal();
    }
  });
});
