div.script:
(function(){
  /* Bossed Up channels are OGFlix Blogger labels. */
  var channelLabels=[
    {label:'Featured',name:'Featured'},
    {label:'MusicVideos',name:'Music Videos'},
    {label:'Movies',name:'Movies'},
    {label:'ShortFilm',name:'Short Films'},
    {label:'Games',name:'Games'},
    {label:'Albums',name:'Albums'}
  ];

  var channels=[];
  var section=document.getElementById('bossed-up-tv-section');
  var bezel=document.getElementById('bossedUpTvBezel');
  var list=document.getElementById('bossedUpChannels');
  var now=document.getElementById('bossedUpNow');

  function esc(s){
    return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');
  }

  function youtubeId(v){
    if(!v)return '';
    var s=String(v).trim();
    if(/^[A-Za-z0-9_-]{6,}$/.test(s))return s;
    var m=s.match(/(?:youtu\.be\/|youtube(?:-nocookie)?\.com\/(?:watch\?v=|embed\/|shorts\/|live\/))([A-Za-z0-9_-]{6,})/i);
    return m?m[1]:'';
  }

  function thumbnail(id){
    return 'https://i.ytimg.com/vi/'+encodeURIComponent(id)+'/hqdefault.jpg';
  }

  function postIsInLabel(post,label){
    var cats=(post&&post.category)||[];
    var target=String(label).replace(/\s+/g,'').toLowerCase();
    return cats.some(function(c){
      var term=String(c.term||'').replace(/\s+/g,'').toLowerCase();
      return term===target;
    });
  }

  function findYouTubeId(post){
    var html=(post&&post.content&&post.content.$t)||(post&&post.summary&&post.summary.$t)||'';
    var box=document.createElement('div');
    box.innerHTML=html;

    var els=box.querySelectorAll(
      'iframe[src],embed[src],video[src],source[src],a[href],*[data-video],*[data-video-id],*[data-youtube],*[data-youtube-id],*[data-url],*[data-src]'
    );

    for(var i=0;i<els.length;i++){
      var el=els[i];
      var vals=[
        el.getAttribute('src'),
        el.getAttribute('href'),
        el.getAttribute('data-video'),
        el.getAttribute('data-video-id'),
        el.getAttribute('data-youtube'),
        el.getAttribute('data-youtube-id'),
        el.getAttribute('data-url'),
        el.getAttribute('data-src')
      ];
      for(var j=0;j<vals.length;j++){
        var id=youtubeId(vals[j]);
        if(id)return id;
      }
    }

    var urls=html.match(/(?:https?:\/\/)?(?:www\.)?(?:youtube\.com\/(?:watch\?v=|embed\/|shorts\/|live\/)[A-Za-z0-9?=&_%.\-\/]+|youtu\.be\/[A-Za-z0-9?=&_%.\-\/]+)/ig)||[];
    for(var k=0;k<urls.length;k++){
      var found=youtubeId(urls[k]);
      if(found)return found;
    }
    return '';
  }

  function renderButtons(){
    if(!list)return;
    list.innerHTML='';

    channels.forEach(function(c,i){
      var btn=document.createElement('button');
      btn.type='button';
      btn.className='bossed-up-channel';
      btn.setAttribute('aria-label','Watch '+c.name+' channel');
      btn.innerHTML=
        '<div class="bossed-up-channel-text">'+
          '<span class="bossed-up-channel-number">CHANNEL '+(i+1)+'</span>'+
          '<span class="bossed-up-channel-name">'+esc(c.name)+'</span>'+
        '</div>';
      btn.addEventListener('click',function(){showChannel(i);});
      list.appendChild(btn);
    });
  }

  function showChannel(index){
    var c=channels[index];
    if(!c||!bezel)return;

    bezel.innerHTML=
      '<div class="bossed-up-tv-preview" style="background-image:url('+esc(thumbnail(c.id))+')">'+
        '<div class="bossed-up-tv-preview-info">'+
          '<div class="bossed-up-tv-preview-title">'+esc(c.videoTitle)+'</div>'+
          '<div class="bossed-up-tv-preview-channel">'+esc(c.name)+' Channel</div>'+
          '<button type="button" class="bossed-up-tv-play">▶ Play Video</button>'+
        '</div>'+
      '</div>';

    var play=bezel.querySelector('.bossed-up-tv-play');
    if(play)play.addEventListener('click',function(){playChannel(index);});

    if(now)now.textContent=c.name+' Channel';

    document.querySelectorAll('.bossed-up-channel').forEach(function(btn,n){
      btn.classList.toggle('active',n===index);
    });
  }

  function showDjVietnamPlaylist(){
    if(!bezel)return;
    bezel.innerHTML=
      '<iframe class="bossed-up-tv-playlist" id="djVietnamTvPlaylist" src="https://www.youtube.com/embed/IdOGl29dLlU?rel=0&amp;modestbranding=1&amp;playsinline=1" title="DJ Vietnam TV" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen="allowfullscreen" loading="eager"></iframe>';
    if(now)now.textContent='DJ Vietnam TV';
    document.querySelectorAll('.bossed-up-channel').forEach(function(btn){
      btn.classList.remove('active');
    });
  }

  function playChannel(index){
    var c=channels[index];
    if(!c||!bezel)return;

    bezel.innerHTML=
      '<iframe class="bossed-up-tv-screen" src="https://www.youtube.com/embed/'+
      encodeURIComponent(c.id)+
      '?rel=0&amp;modestbranding=1&amp;playsinline=1" title="'+esc(c.videoTitle)+
      '" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen="allowfullscreen"></iframe>';

    if(now)now.textContent=c.name+' Channel';

    document.querySelectorAll('.bossed-up-channel').forEach(function(btn,n){
      btn.classList.toggle('active',n===index);
    });
  }

  function loadChannel(channel){
    var url='/feeds/posts/default/-/'+encodeURIComponent(channel.label)+'?alt=json&max-results=50';

    return fetch(url,{credentials:'same-origin',cache:'no-store'})
      .then(function(r){
        if(!r.ok)throw new Error('Label feed failed: '+channel.label);
        return r.json();
      })
      .then(function(data){
        var posts=(data.feed&&data.feed.entry)||[];
        var videos=[];
        var seen={};

        posts.forEach(function(post){
          /* Support compact Blogger labels and labels with spaces. */
          if(!postIsInLabel(post,channel.label) &&
             !(channel.label==='MusicVideos' && postIsInLabel(post,'Music Videos')) &&
             !(channel.label==='ShortFilm' && postIsInLabel(post,'Short Films')) &&
             !(channel.label==='Albums' && (postIsInLabel(post,'MusicAlbums') || postIsInLabel(post,'Music Albums')))){
            return;
          }

          var id=findYouTubeId(post);
          if(!id||seen[id])return;
          seen[id]=true;

          videos.push({
            id:id,
            videoTitle:(post.title&&post.title.$t)||channel.name,
            name:channel.name
          });
        });

        if(!videos.length)return null;

        /* Random video within the selected label channel. */
        return videos[Math.floor(Math.random()*videos.length)];
      });
  }

  function loadAllChannels(){
    if(!section)return;

    section.style.display='';

    Promise.all(channelLabels.map(function(channel){
      return loadChannel(channel).then(function(video){
        if(!video)return null;
        return {
          id:video.id,
          videoTitle:video.videoTitle,
          name:channel.name
        };
      }).catch(function(){return null;});
    })).then(function(results){
      channels=results.filter(function(x){return !!x;});

      if(!channels.length){
        showDjVietnamPlaylist();
        return;
      }

      section.style.display='';
      renderButtons();

      /* Keep DJ Vietnam TV playlist as the Bossed Up default screen.
         Channel buttons can still switch the screen to an individual video. */
      showDjVietnamPlaylist();
    });
  }

  if(document.readyState==='loading'){
    document.addEventListener('DOMContentLoaded',loadAllChannels);
  }else{
    loadAllChannels();
  }
})();

body.script:
    //

    // Keep the copyright year current.
    var yearEl = document.getElementById('copyright-year');
    if (yearEl) yearEl.textContent = new Date().getFullYear();

    // PROTECTION
    document.addEventListener("keydown", function(e) {
        if (e.ctrlKey && (e.key === "u" || e.key === "U" || e.key === "s" || e.key === "S")) e.preventDefault();
        if (e.key === "F12" || (e.ctrlKey && e.shiftKey && e.key === "I")) e.preventDefault();
    });
    (function(){})();

    const API_KEY = '3b522d97585d4de7c6c1d0f346940389';
    const IMG_BASE = 'https://image.tmdb.org/t/p/original';
    const IMG_W500 = 'https://image.tmdb.org/t/p/w500';
    const TMDB_BASE = 'https://api.themoviedb.org/3';

    /* IMDb integration: IMDb's licensed API is accessed through AWS Data Exchange.
       Keep credentials off the public Blogger template. Set IMDB_PROXY_URL to your
       own server-side proxy that accepts ?id=tt1234567 and returns IMDb JSON.
       If it is blank, OGFlix safely falls back to TMDB metadata and an IMDb link. */
    const IMDB_PROXY_URL = '';
    // JOIN / PROFILE: optional only; never blocks page rendering.
    function openJoinProfile() {
        var gate = document.getElementById('profile-gate');
        if (!gate) return;
        gate.classList.add('join-open');
        gate.setAttribute('aria-hidden','false');
        closeJoinMenu();
    }
    function closeJoinProfile() {
        var gate = document.getElementById('profile-gate');
        if (!gate) return;
        gate.classList.remove('join-open');
        gate.setAttribute('aria-hidden','true');
    }
    function selectProfile(name) {
        try { localStorage.setItem('conflix_user', name); } catch (e) {}
        closeJoinProfile();
    }
    function checkProfile() { closeJoinProfile(); }
    function switchProfile() { openJoinProfile(); }
// UI
    window.addEventListener('scroll', function() {
        var nav = document.getElementById('nav');
        if (!nav) return;
        if(window.scrollY > 50) nav.classList.add('black'); else nav.classList.remove('black');
    });

    // Mobile channel menu — intentionally separate from the desktop menu.
    (function(){
        var mobileMenu = document.getElementById('mobile-menu');
        if(!mobileMenu) return;

        mobileMenu.innerHTML = '';

        var mobileItems = [
            ['OG Exclusives','http://ogflixtv.blogspot.com/p/exclusives.html'],
            ['All Movies','https://ogflixtv.blogspot.com/search/label/Movies'],
            ['Music Videos','https://ogflixtv.blogspot.com/search/label/MusicVideos'],
            ['Short Films','https://ogflixtv.blogspot.com/search/label/ShortFilm'],
            ['Mixtapes','http://ogflixtv.blogspot.com/p/mixtapes.html'],
            ['Interviews','http://ogflixtv.blogspot.com/p/interviews.html'],
            ['Upcoming','http://ogflixtv.blogspot.com/p/upcoming.html'],
            ['Live TV','http://ogflixtv.blogspot.com/p/live.html'],
            ['Submit Yours','http://ogflixtv.blogspot.com/p/submission.html']
        ];

        mobileItems.forEach(function(item){
            var a = document.createElement('a');
            var icon = document.createElement('span');
            var label = document.createElement('span');

            a.href = item[1];
            a.className = 'mobile-link';
            icon.setAttribute('aria-hidden','true');
            label.className = 'mobile-link-label';
            label.textContent = item[0];

            a.appendChild(icon);
            a.appendChild(label);
            a.addEventListener('click', function(){ mobileMenu.classList.remove('open'); });
            mobileMenu.appendChild(a);
        });
    })();

    function toggleMobileMenu() {
        var menu = document.getElementById('mobile-menu');
        if (menu) menu.classList.toggle('open');
    }
    function toggleSearch() {
        var box = document.getElementById('search-box');
        var main = document.getElementById('main-view');
        var results = document.getElementById('search-results-container');
        if (!box) return;
        box.classList.toggle('open');
        if(box.classList.contains('open')) {
            var input = document.getElementById('search-input');
            if (input) input.focus();
        } else {
            if (results) results.classList.add('hidden');
            document.body.classList.remove('og-search-page');
            if (main) main.classList.remove('hidden');
        }
    }

    function toggleJoinMenu(event) {
        if (event) event.stopPropagation();
        var selector = document.getElementById('joinSelector');
        var button = document.getElementById('joinButton');
        if (!selector) return;
        var open = selector.classList.toggle('open');
        if (button) button.setAttribute('aria-expanded', open ? 'true' : 'false');
    }
    function closeJoinMenu() {
        var selector = document.getElementById('joinSelector');
        var button = document.getElementById('joinButton');
        if (selector) selector.classList.remove('open');
        if (button) button.setAttribute('aria-expanded','false');
    }
    document.addEventListener('click', function(e){
        var selector = document.getElementById('joinSelector');
        if (selector && !selector.contains(e.target)) closeJoinMenu();
    });
    document.addEventListener('keydown', function(e){
        if (e.key === 'Escape') { closeJoinMenu(); closeJoinProfile(); }
    });
    const searchInput = document.getElementById('search-input');
    if (searchInput) searchInput.addEventListener('keyup', async (e) => {
        if(e.key === 'Enter') {
            const query = e.target.value;
            const main = document.getElementById('main-view');
            const resultsBox = document.getElementById('search-results-container');
            const grid = document.getElementById('search-grid');
            document.body.classList.add('og-search-page');
            if (grid) grid.classList.remove('label-mode');
            main.classList.add('hidden');
            resultsBox.classList.remove('hidden');
            grid.innerHTML = '<div class="text-gray-500">Loading...</div>';

            const res = await fetch(`/feeds/posts/default?alt=json&q=${encodeURIComponent(query)}`);
            const data = await res.json();
            const posts = (data.feed && data.feed.entry) ? data.feed.entry : [];

            if(!posts.length) { grid.innerHTML = 'No results found.'; return; }
            grid.innerHTML = '';
            posts.forEach(post => {
                const link = post.link.find(l=>l.rel==='alternate').href;
                let img = getMatch(post.content.$t, 'poster-url');
                if(!img && post.media$thumbnail) img = post.media$thumbnail.url.replace('/s72-c/', '/w342/'); 
                grid.innerHTML += `<div class="row-poster" onclick="window.location.href='${link}'"><img src="${img}" class="w-full h-full object-cover rounded"/></div>`;
            });
        }
    });

    // APP LOGIC
    // Keep the homepage shell visible even if an optional third-party dependency fails.
    (function(){
        var home = (window.location.pathname === '/' || window.location.pathname === '/index.html' || window.location.pathname === '');
        var mainView = document.getElementById('main-view');
        if (home && mainView) mainView.classList.remove('hidden');
    })();
    const isHome = (window.location.pathname === '/' || window.location.pathname === '/index.html' || window.location.pathname === '') && !window.location.pathname.match(/^\/p\//i);
    const isSingle = document.getElementById('app-player') !== null;
    const isLabel = document.getElementById('label-loader') !== null;

    if (isHome) {
        initHome();
    } else if (isSingle) {
        initPlayer();
    } else if (isLabel) {
        /* Keep label results in normal document flow, directly before the main/footer.
           The navigation stays in #app-root; the catalog itself is moved outside that
           wrapper so its full height is measured before the footer is rendered. */
        const resultsFlow = document.getElementById('search-results-container');
        const mainFlow = document.getElementById('main-view');
        if (resultsFlow && mainFlow && mainFlow.parentNode) {
            mainFlow.parentNode.insertBefore(resultsFlow, mainFlow);
        }

        const path = window.location.pathname;
        const rawLabel = decodeURIComponent(path.split('/').pop() || '').trim();
        const results = document.getElementById('search-results-container');
        const grid = document.getElementById('search-grid');
        const main = document.getElementById('main-view');
        if (main) main.classList.add('hidden');
        document.body.classList.add('og-search-page');
        if (grid) grid.classList.add('label-mode');
        if (results) results.classList.remove('hidden');
        loadLabelPage(rawLabel, grid);
    }

    async function loadLabelPage(rawLabel, grid) {
        if (!grid) return;
        const aliases = {
            'MusicVideos': ['MusicVideos', 'Music Videos'],
            'Music Videos': ['MusicVideos', 'Music Videos'],
            'MusicAlbums': ['MusicAlbums', 'Music Albums', 'Albums'],
            'Albums': ['MusicAlbums', 'Music Albums', 'Albums'],
            'Featured': ['Featured'],
            'Movies': ['Movies'],
            'ShortFilm': ['ShortFilm', 'Short Films'],
            'Short Films': ['ShortFilm', 'Short Films'],
            'Games': ['Games']
        };
        const candidates = aliases[rawLabel] || [rawLabel];
        let posts = [];
        let matchedLabel = rawLabel;

        for (let i = 0; i < candidates.length; i++) {
            const label = candidates[i];
            try {
                let startIndex = 1;
                let collected = [];
                let foundAny = false;
                while (startIndex <= 500) {
                    const url = '/feeds/posts/default/-/' + encodeURIComponent(label) + '?alt=json&max-results=50&start-index=' + startIndex;
                    const res = await fetch(url, { credentials: 'same-origin', cache: 'no-store' });
                    if (!res.ok) break;
                    const data = await res.json();
                    const found = data.feed && data.feed.entry ? data.feed.entry : [];
                    if (!found.length) break;
                    foundAny = true;
                    collected = collected.concat(found);
                    if (found.length < 50) break;
                    startIndex += 50;
                }
                if (foundAny) {
                    posts = collected;
                    matchedLabel = label;
                    break;
                }
            } catch (e) {
                console.warn('OGFlix label feed failed:', label, e);
            }
        }

        if (!posts.length) {
            grid.innerHTML = '<div class="label-empty"><i class="bx bx-folder-open"></i><h2>No content found</h2><p>This section does not have any published posts yet.</p></div>';
            return;
        }

        const labelUrl = '/search/label/' + encodeURIComponent(matchedLabel);
        const itemCount = posts.length;
        const titleText = matchedLabel === 'MusicVideos' ? 'Music Videos' : (matchedLabel === 'ShortFilm' ? 'Short Films' : (matchedLabel === 'MusicAlbums' ? 'Albums' : matchedLabel));

        function postInfo(post) {
            const linkObj = post.link && post.link.find(function(l) { return l.rel === 'alternate'; });
            if (!linkObj) return null;
            const link = linkObj.href;
            const title = post.title && post.title.$t ? post.title.$t : 'OGFlix';
            const content = post.content && post.content.$t ? post.content.$t : (post.summary && post.summary.$t ? post.summary.$t : '');
            let img = getMatch(content, 'poster-url') || getMatch(content, 'cover-url');
            if (!img && post.media$thumbnail && post.media$thumbnail.url) img = post.media$thumbnail.url.replace('/s72-c/', '/w500/');
            if (!img) img = 'data:image/svg+xml;charset=UTF-8,%3Csvg xmlns="http://www.w3.org/2000/svg" width="500" height="750"%3E%3Crect width="500" height="750" fill="%23151515"/%3E%3Ctext x="250" y="375" text-anchor="middle" dominant-baseline="middle" fill="%23777" font-family="Arial" font-size="34"%3EOGFlix%3C/text%3E%3C/svg%3E';
            return { link: link, title: title, img: img, published: post.published && post.published.$t ? post.published.$t : '', comments: post.thr$total && post.thr$total.$t ? parseInt(post.thr$total.$t,10) || 0 : 0 };
        }

        const allItems = posts.map(postInfo).filter(Boolean);

        // Shuffle the array randomly for randomized sections
        const shuffledPopular = allItems.slice();
        for (let i = shuffledPopular.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            const tmp = shuffledPopular[i];
            shuffledPopular[i] = shuffledPopular[j];
            shuffledPopular[j] = tmp;
        }
        const popularItems = shuffledPopular.slice(0, 10);

        const shuffledNew = allItems.slice();
        for (let i = shuffledNew.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            const tmp = shuffledNew[i];
            shuffledNew[i] = shuffledNew[j];
            shuffledNew[j] = tmp;
        }
        const newItems = shuffledNew.slice(0, 10);

        function renderLabelCards(items, ranked) {
            return items.map(function(item, idx){
                return '<a class="label-card" href="' + escapeHtml(item.link) + '" title="' + escapeHtml(item.title) + '">' +
                    (ranked ? '<span class="label-rank">' + (idx + 1) + '</span>' : '') +
                    '<img src="' + escapeHtml(item.img) + '" alt="' + escapeHtml(item.title) + '" loading="lazy"/>' +
                    '<div class="label-card-info"><div class="label-card-title">' + escapeHtml(item.title) + '</div><div class="label-card-meta">OGFlix</div></div></a>';
            }).join('');
        }

        let html = '<div class="label-page-shell">' +
            '<div class="label-page-heading"><h1>' + escapeHtml(titleText) + '</h1><p>' + itemCount + ' item' + (itemCount === 1 ? '' : 's') + '</p></div>' +
            '<section class="label-section"><div class="label-section-head"><div><h2 class="label-section-title">Top 10</h2><p class="label-section-subtitle"></p></div><a class="label-section-link" href="' + escapeHtml(labelUrl) + '">See All <i class="bx bx-chevron-right"></i></a></div><div class="label-horizontal">' + renderLabelCards(popularItems, true) + '</div></section>' +
            '<section class="label-section"><div class="label-section-head"><div><h2 class="label-section-title">New Releases</h2><p class="label-section-subtitle"></p></div><a class="label-section-link" href="' + escapeHtml(labelUrl) + '">See All <i class="bx bx-chevron-right"></i></a></div><div class="label-horizontal">' + renderLabelCards(newItems, false) + '</div></section>' +
            '<section class="label-section"><div class="label-section-head"><div><h2 class="label-section-title">All Videos</h2><p class="label-section-subtitle"></p></div><a class="label-section-link" href="' + escapeHtml(labelUrl) + '">Watch Video <i class="bx bx-chevron-right"></i></a></div><div class="label-all-grid">';

        allItems.forEach(function(item){
            html += '<a class="label-card" href="' + escapeHtml(item.link) + '" title="' + escapeHtml(item.title) + '"><img src="' + escapeHtml(item.img) + '" alt="' + escapeHtml(item.title) + '" loading="lazy"/><div class="label-card-info"><div class="label-card-title">' + escapeHtml(item.title) + '</div><div class="label-card-meta">OGFlix</div></div></a>';
        });
        html += '</div></section></div>';
        grid.innerHTML = html;
        document.querySelectorAll('.menu-widget a, .mobile-link').forEach(function(link){
            link.classList.remove('label-active');
            const href = link.getAttribute('href') || '';
            if (href.indexOf('/search/label/') !== -1 && href.toLowerCase().indexOf(encodeURIComponent(matchedLabel).toLowerCase()) !== -1) {
                link.classList.add('label-active');
            }
        });
    }

    async function initHome() {
        try {
            const res = await fetch('/feeds/posts/default?alt=json&max-results=12');
            const data = await res.json();
            const posts = data.feed && data.feed.entry ? data.feed.entry : [];
            if (posts.length) {
                const randomPost = posts[Math.floor(Math.random() * posts.length)];
                const title = randomPost.title ? randomPost.title.$t : 'OGFlix';
                const content = randomPost.content ? randomPost.content.$t : '';
                const linkObj = randomPost.link && randomPost.link.find(function(l){return l.rel==='alternate';});
                const link = linkObj ? linkObj.href : '/';
                const tmdb = await fetchTMDB(title);
                const backdrop = tmdb && tmdb.backdrop_path
                    ? IMG_BASE + tmdb.backdrop_path
                    : (getMatch(content, 'backdrop-url') || getMatch(content, 'poster-url') || '');
                const desc = tmdb && tmdb.overview
                    ? tmdb.overview
                    : (getMatch(content, 'data-desc') || 'Watch The Hottest Music and Videos on OGFlix.');
                if (backdrop) document.getElementById('banner').style.backgroundImage = "url('" + backdrop.replace(/'/g,"%27") + "')";
                document.getElementById('banner-title').innerText = title;
                document.getElementById('banner-desc').innerText = desc;
                const openLink = function(){ window.location.href = link; };
                document.getElementById('btn-play').onclick = openLink;
                document.getElementById('btn-more').onclick = openLink;
            }
        } catch(e) {}

        loadFeaturedBanner('/feeds/posts/default/-/Featured?alt=json&max-results=10', 'featured-banner-section');
        loadRow('/feeds/posts/default?alt=json&max-results=12', 'row-trending', 'Trending Now');
        loadRow('/feeds/posts/default/-/MusicVideos?alt=json&max-results=50', 'row-music-videos', 'Music Videos', false, false, true);
        loadRow('/feeds/posts/default/-/MusicAlbums?alt=json&max-results=12', 'row-albums', 'Albums');
        loadRow('/feeds/posts/default/-/Movies?alt=json&max-results=50', 'row-movies', 'Movies', false, false, true);
        loadRow('/feeds/posts/default/-/Games?alt=json&max-results=12', 'row-comedy', 'Games');
        loadTop10('/feeds/posts/default/-/MusicVideos?alt=json&max-results=50', 'row-top-music-videos', 'Top 10 Music Videos');
        loadRow('/feeds/posts/default/-/FeaturedMovies?alt=json&max-results=12', 'row-featured-movies', 'Featured Movies');
        loadRow('/feeds/posts/default/-/MovieOfTheWeek?alt=json&max-results=12', 'row-movie-of-week', 'Movie Of The Week');
        loadRow('/feeds/posts/default/-/SongOfTheWeek?alt=json&max-results=12', 'row-song-of-week', 'Song Of The Week');
        loadRow('/feeds/posts/default/-/ArtistOfTheWeek?alt=json&max-results=12', 'row-artist-of-week', 'Featured Artists');
        loadRow('/feeds/posts/default/-/DJ?alt=json&max-results=12', 'row-djs', 'Featured DJs');
        loadRow('/feeds/posts/default/-/Producer?alt=json&max-results=12', 'row-producers', 'Featured Producers');
        loadRow('/feeds/posts/default/-/Interviews?alt=json&max-results=12', 'row-interviews', 'Interviews');
        loadRow('/feeds/posts/default/-/Tutorials?alt=json&max-results=12', 'row-tutorials', 'Tutorials');
        loadRow('/feeds/posts/default/-/ShortFilm?alt=json&max-results=50', 'row-shortfilm', 'Short Films', false, false, true);
        loadRow('/feeds/posts/default?alt=json&max-results=50', 'row-recommended', 'Videos To Check Out', false, false, true);
    }

    function loadRandomCategoryRow(label,containerId,title,limit){
  var container=document.getElementById(containerId);
  if(!container)return;
  var labels=Array.isArray(label)?label:[label];
  var requests=labels.map(function(l){
    return fetch('/feeds/posts/default/-/'+encodeURIComponent(l)+'?alt=json&max-results=50')
      .then(function(r){return r.ok?r.json():{feed:{entry:[]}};})
      .catch(function(){return {feed:{entry:[]}};});
  });
  Promise.all(requests).then(function(results){
    var entries=[];
    results.forEach(function(data){
      if(data&&data.feed&&data.feed.entry) entries=entries.concat(data.feed.entry);
    });
    var seen={};
    entries=entries.filter(function(e){
      var id=(e.id&&e.id.$t)||'';
      if(!id||seen[id])return false;
      seen[id]=true;
      return true;
    });
    for(var i=entries.length-1;i>0;i--){
      var j=Math.floor(Math.random()*(i+1)),tmp=entries[i];
      entries[i]=entries[j];entries[j]=tmp;
    }
    entries=entries.slice(0,limit||10);
    if(entries.length){
      renderEntriesIntoRow(entries,container,title);
      container.parentElement.style.display='';
    }else{
      container.parentElement.style.display='none';
    }
  });
}

function renderEntriesIntoRow(entries,container,title){
  container.innerHTML='';
  entries.forEach(function(entry){
    var link=(entry.link||[]).filter(function(x){return x.rel==='alternate';})[0];
    var href=link?link.href:'#';
    var titleText=(entry.title&&entry.title.$t)||'Untitled';
    var img='';
    var thumb=entry.media$thumbnail;
    if(thumb&&thumb.url)img=thumb.url.replace(/\/s[0-9]+(-c)?\//,'/s600/');
    var card=document.createElement('a');
    card.className='ogflix-card';
    card.href=href;
    card.innerHTML='<div class="ogflix-card-image">'+
      (img?'<img loading="lazy" src="'+img+'" alt="">':'<div class="ogflix-card-placeholder"></div>')+
      '</div><div class="ogflix-card-title">'+titleText+'</div>';
    container.appendChild(card);
  });
}
async function loadRow(url, containerId, title, isRank=false, isGrid=false, randomOrder=false) {
        const container = document.getElementById(containerId);
        if (!container) return;
        try {
            const res = await fetch(url);
            if (!res.ok) { container.innerHTML = ''; container.style.display = 'none'; return; }
            const data = await res.json();
            let posts = data.feed && data.feed.entry ? data.feed.entry.slice() : [];
            if (randomOrder && posts.length > 1) {
                for (let i = posts.length - 1; i > 0; i--) {
                    const j = Math.floor(Math.random() * (i + 1));
                    const tmp = posts[i]; posts[i] = posts[j]; posts[j] = tmp;
                }
                posts = posts.slice(0, 12);
            }
            /* Homepage All-Time Popular Posts: exactly 8 cards in a 4 x 2 grid. */
            if (containerId === 'row-recommended') {
                posts = posts.slice(0, 8);
            }
            if (!posts.length) {
                container.innerHTML = '';
                container.style.display = 'none';
                return;
            }

            container.style.display = '';
            let html = '<div class="section-heading"><h2 class="row-title">' + escapeHtml(title) + '</h2></div><div class="row-posters">';
            let renderedCount = 0;
            posts.forEach(function(post) {
                const linkObj = post.link && post.link.find(function(l){return l.rel==='alternate';});
                if (!linkObj) return;
                renderedCount++;
                const link = linkObj.href;
                const content = post.content ? post.content.$t : '';
                let img = getMatch(content, 'poster-url') || getMatch(content, 'cover-url');
                if (!img && post.media$thumbnail && post.media$thumbnail.url) {
                    img = post.media$thumbnail.url.replace('/s72-c/', '/w342/');
                }
                if (!img) img = "data:image/svg+xml;charset=UTF-8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='342' height='513' viewBox='0 0 342 513'%3E%3Crect width='342' height='513' fill='%23151515'/%3E%3Ctext x='171' y='257' text-anchor='middle' dominant-baseline='middle' fill='%23777' font-family='Arial' font-size='28'%3EOGFlix%3C/text%3E%3C/svg%3E";
                const postTitle = post.title ? post.title.$t : title;
                html += '<a class="content-card" href="' + escapeHtml(link) + '" aria-label="' + escapeHtml(postTitle) + '">' +
                    '<img src="' + escapeHtml(img) + '" alt="' + escapeHtml(postTitle) + '" loading="lazy"/>' +
                    '<div class="content-card-info"><div class="content-card-title">' + escapeHtml(postTitle) + '</div><div class="content-card-meta">OGFlix</div></div>' +
                    '</a>';
            });
            if (!renderedCount) { container.innerHTML = ''; container.style.display = 'none'; return; }
            html += '</div>';
            container.innerHTML = html;
        } catch(e) {
            console.error('OGFlix row load error:', e);
            container.innerHTML = ''; container.style.display = 'none';
        }
    }

    function renderPlaceholderSection(container, title) {
        if (!container) return;
        const labels = ['Coming Soon', 'Content Needed', 'Coming Soon', 'Content Needed', 'Coming Soon', 'Content Needed'];
        let cards = '';
        labels.forEach(function(label) {
            cards += '<div class="placeholder-card"><div class="placeholder-card-inner"><span class="placeholder-icon"><i class="bx bx-movie-play"></i></span><div class="placeholder-title">' + escapeHtml(label) + '</div><div class="placeholder-copy">Add OGFlix content to this section.</div></div></div>';
        });
        container.innerHTML = '<section class="placeholder-section"><h2 class="placeholder-heading">' + escapeHtml(title) + '</h2><div class="placeholder-grid">' + cards + '</div><div class="home-placeholder-note">This area is ready for content.</div></section>';
    }

    function parseMusicVideoTitle(postTitle) {
        const rawTitle = String(postTitle || '').trim();
        const separator = ' - ';
        const splitAt = rawTitle.indexOf(separator);
        if (splitAt > 0) {
            return {
                artist: rawTitle.slice(0, splitAt).trim(),
                song: rawTitle.slice(splitAt + separator.length).trim(),
                full: rawTitle
            };
        }
        return { artist: '', song: rawTitle, full: rawTitle };
    }

    async function loadTop10(url, containerId, title) {
        const container = document.getElementById(containerId);
        try {
            const res = await fetch(url);
            const data = await res.json();
            let posts = data.feed && data.feed.entry ? data.feed.entry.slice() : [];
            if(!posts.length) { container.innerHTML = ''; container.style.display = 'none'; return; }
            for (let i = posts.length - 1; i > 0; i--) {
                const j = Math.floor(Math.random() * (i + 1));
                const tmp = posts[i]; posts[i] = posts[j]; posts[j] = tmp;
            }
            posts = posts.slice(0, 10);
            let html = `<h2 class="row-title">${title}</h2><div class="row-posters">`;
            posts.forEach((post, idx) => {
                const link = post.link.find(l=>l.rel==='alternate').href;
                let img = getMatch(post.content.$t, 'poster-url');
                if(!img && post.media$thumbnail) img = post.media$thumbnail.url.replace('/s72-c/', '/w342/');
                const parsedTitle = parseMusicVideoTitle(post.title ? post.title.$t : '');
                const fullTitle = parsedTitle.full;
                html += `<a class="rank-container" href="${escapeHtml(link)}" title="${escapeHtml(fullTitle)}" aria-label="${escapeHtml(fullTitle)}"><span class="rank-num">${idx + 1}</span><img src="${escapeHtml(img)}" class="rank-img" alt="${escapeHtml(fullTitle)}"/></a>`;
            });
            html += `</div>`;
            container.innerHTML = html;
        } catch(e) { if(container){ container.innerHTML = ''; container.style.display = 'none'; } }
    }

    async function loadFeaturedBanner(url, containerId) {
        const container = document.getElementById(containerId);
        if (!container) return;
        try {
            const res = await fetch(url);
            if (!res.ok) throw new Error('Featured feed failed');
            const data = await res.json();
            let posts = (data.feed && data.feed.entry) ? data.feed.entry.slice(0, 10) : [];
            if (!posts.length) {
                container.innerHTML = '';
                container.style.display = 'none';
                return;
            }

            const getPostImage = function(post) {
                let img = getMatch(post.content ? post.content.$t : '', 'backdrop-url') || getMatch(post.content ? post.content.$t : '', 'poster-url');
                if (!img && post.media$thumbnail) img = post.media$thumbnail.url.replace('/s72-c/', '/w1200/');
                return img || '';
            };
            const getPostDescription = function(post) {
                const content = post.content ? post.content.$t : '';
                const desc = getMatch(content, 'data-desc') || getMatch(content, 'description');
                if (desc) return String(desc).replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
                return 'Watch This Featured Presentation on OGFlix.';
            };
            const safeUrl = function(urlValue) {
                try {
                    const u = new URL(urlValue, window.location.href);
                    if (u.protocol === 'http:' || u.protocol === 'https:') return u.href;
                } catch(e) {}
                return '#';
            };

            container.style.display = '';
            let html = '<div class="featured-banner-heading"><h2><i class="bx bxs-star"></i> Featured</h2></div>' +
                '<div class="featured-banner-slider">' +
                '<button class="featured-banner-arrow featured-banner-prev" type="button" aria-label="Previous Featured" onclick="moveFeaturedBanner(-1)">&#10094;</button>' +
                '<div class="featured-banner-track" id="featured-banner-track">';

            posts.forEach(function(post, index) {
                const linkObj = post.link && post.link.find(function(l){ return l.rel === 'alternate'; });
                const link = safeUrl(linkObj ? linkObj.href : '#');
                const title = post.title ? post.title.$t : 'Featured';
                const image = getPostImage(post);
                const description = getPostDescription(post);
                const background = image ? "background-image:url('" + image.replace(/'/g, "%27") + "')" : '';
                html += '<article class="featured-banner-slide" style="' + background + '" data-href="' + escapeHtml(link) + '" role="link" tabindex="0">' +
                    '<div class="featured-banner-content">' +
                    '<div class="featured-banner-badge"><i class="bx bxs-star"></i> Featured</div>' +
                    '<h3 class="featured-banner-title">' + escapeHtml(title) + '</h3>' +
                    '<p class="featured-banner-description">' + escapeHtml(description) + '</p>' +
                    '<a class="featured-banner-watch" href="' + escapeHtml(link) + '"><i class="bx bx-play"></i> Watch Now</a>' +
                    '</div></article>';
            });

            html += '</div>' +
                '<button class="featured-banner-arrow featured-banner-next" type="button" aria-label="Next Featured" onclick="moveFeaturedBanner(1)">&#10095;</button>' +
                '<div class="featured-banner-dots" id="featured-banner-dots">';
            posts.forEach(function(_, index) {
                html += '<button class="featured-banner-dot' + (index === 0 ? ' active' : '') + '" type="button" aria-label="Featured ' + (index + 1) + '" onclick="goToFeaturedBanner(' + index + ')"></button>';
            });
            html += '</div></div>';
            container.innerHTML = html;
            container.querySelectorAll('.featured-banner-slide').forEach(function(slide){
                const href = slide.getAttribute('data-href');
                if (!href) return;
                slide.addEventListener('click', function(e){
                    if (e.target.closest('a,button')) return;
                    window.location.assign(href);
                });
                slide.addEventListener('keydown', function(e){
                    if ((e.key === 'Enter' || e.key === ' ') && !e.target.closest('a,button')) {
                        e.preventDefault();
                        window.location.assign(href);
                    }
                });
            });

            window.featuredBannerIndex = 0;
            window.featuredBannerCount = posts.length;
            window.featuredBannerContainer = container;
            if (window.featuredBannerTimer) clearInterval(window.featuredBannerTimer);
            window.featuredBannerTimer = setInterval(function(){
                if (!document.hidden && !container.matches(':hover')) moveFeaturedBanner(1);
            }, 6000);
            let touchStartX = 0;
            const slider = container.querySelector('.featured-banner-slider');
            if (slider) {
                slider.addEventListener('touchstart', function(e){ touchStartX = e.changedTouches[0].clientX; }, {passive:true});
                slider.addEventListener('touchend', function(e){
                    const dx = e.changedTouches[0].clientX - touchStartX;
                    if (Math.abs(dx) > 45) moveFeaturedBanner(dx < 0 ? 1 : -1);
                }, {passive:true});
            }
            container.querySelectorAll('.featured-banner-slide').forEach(function(slide,i){
                slide.setAttribute('aria-hidden', i === 0 ? 'false' : 'true');
            });
        } catch(e) {
            container.innerHTML = '<div class="featured-banner-empty"><div><strong>Featured Content Coming Soon</strong><br/><span class="home-placeholder-note">This area is ready for featured content.</span></div></div>';
        }
    }

    window.moveFeaturedBanner = function(direction) {
        const count = window.featuredBannerCount || 0;
        if (!count) return;
        let index = (window.featuredBannerIndex || 0) + direction;
        if (index < 0) index = count - 1;
        if (index >= count) index = 0;
        goToFeaturedBanner(index);
    };

    window.goToFeaturedBanner = function(index) {
        const track = document.getElementById('featured-banner-track');
        const dots = document.querySelectorAll('.featured-banner-dot');
        if (!track) return;
        window.featuredBannerIndex = index;
        track.style.transform = 'translate3d(-' + (index * 100) + '%,0,0)';
        dots.forEach(function(dot, i){ dot.classList.toggle('active', i === index); });
        track.querySelectorAll('.featured-banner-slide').forEach(function(slide, i){ slide.setAttribute('aria-hidden', i === index ? 'false' : 'true'); });
    };

    document.addEventListener('keydown', function(e){
        const featured=document.getElementById('featured-banner-section');
        if(!featured || !document.getElementById('featured-banner-track')) return;
        if(e.key==='ArrowLeft') moveFeaturedBanner(-1);
        if(e.key==='ArrowRight') moveFeaturedBanner(1);
    });

    function getYouTubeId(url) {
        if (!url) return null;
        try {
            const u = new URL(url, window.location.href);
            const host = u.hostname.toLowerCase().replace(/^www\./, '');
            if (host === 'youtu.be') return u.pathname.split('/').filter(Boolean)[0] || null;
            if (host === 'youtube.com' || host === 'm.youtube.com' || host === 'music.youtube.com') {
                if (u.pathname === '/watch') return u.searchParams.get('v');
                if (u.pathname.indexOf('/embed/') === 0) return u.pathname.split('/')[2] || null;
                if (u.pathname.indexOf('/shorts/') === 0) return u.pathname.split('/')[2] || null;
                if (u.pathname.indexOf('/live/') === 0) return u.pathname.split('/')[2] || null;
            }
        } catch(e) {}
        return null;
    }

    function isYouTubeUrl(url) { return !!getYouTubeId(url); }

    function youtubeEmbedUrl(url) {
        const id = getYouTubeId(url);
        if (!id) return url;
        // Request unmuted autoplay first; the player falls back to muted only when the browser blocks sound autoplay.
        return 'https://www.youtube.com/embed/' + encodeURIComponent(id) +
               '?autoplay=1&mute=0&rel=0&playsinline=1&enablejsapi=1&origin=' +
               encodeURIComponent(window.location.origin);
    }

    function isDirectVideoUrl(url) {
        if (!url) return false;
        try {
            const u = new URL(url, window.location.href);
            return /\.(mp4|webm|ogg|m4v)(?:$|\?)/i.test(u.pathname + u.search);
        } catch(e) {
            return /\.(mp4|webm|ogg|m4v)(?:$|\?)/i.test(url);
        }
    }

    async function fetchYouTubeMetadata(id) {
        try {
            const res = await fetch('https://www.youtube.com/oembed?url=' +
                encodeURIComponent('https://www.youtube.com/watch?v=' + id) +
                '&format=json');
            if (!res.ok) return null;
            return await res.json();
        } catch(e) {
            return null;
        }
    }

    /* Resolve a YouTube song/video URL into real streaming links across
       supported music services instead of sending visitors to generic
       service searches. Songlink/Odesli matches the supplied song URL. */
    async function fetchSongLinks(url) {
        if (!url) return null;
        try {
            const endpoint = 'https://api.song.link/v1-alpha.1/links?url=' +
                encodeURIComponent(url);
            const res = await fetch(endpoint);
            if (!res.ok) return null;
            const data = await res.json();
            if (data && data.linksByPlatform) {
                data.ogflixSmartLink = data.pageUrl || data.shortUrl || '';
                if (data.ogflixSmartLink) {
                    try {
                        const smart = new URL(data.ogflixSmartLink);
                        smart.hostname = 'album.link';
                        data.ogflixAlbumLink = smart.toString();
                    } catch(e) {
                        data.ogflixAlbumLink = '';
                    }
                }
                return data;
            }
            return null;
        } catch(e) {
            return null;
        }
    }

    /* TMDB exposes where a movie/TV title can be watched in a region.
       The returned link is the title's provider/watch page rather than
       pretending a provider URL is a direct playback URL. */
    function getImdbIdFromContent(content) {
        const raw = String(content || '');
        const match = raw.match(/(?:imdb(?:-id|_id)?|data-imdb-id)\s*[:=]\s*[\"']?(tt\d{7,10})/i);
        if (match) return match[1];
        const urlMatch = raw.match(/imdb\.com\/(?:title\/)?(tt\d{7,10})/i);
        return urlMatch ? urlMatch[1] : '';
    }

    async function fetchIMDbMetadata(imdbId) {
        if (!imdbId) return null;
        if (!IMDB_PROXY_URL) return { id: imdbId, url: 'https://www.imdb.com/title/' + encodeURIComponent(imdbId) + '/' };
        try {
            const separator = IMDB_PROXY_URL.indexOf('?') >= 0 ? '&' : '?';
            const res = await fetch(IMDB_PROXY_URL + separator + 'id=' + encodeURIComponent(imdbId), { headers: { 'Accept':'application/json' } });
            if (!res.ok) return null;
            const data = await res.json();
            const d = data && (data.data || data.result || data.title || data);
            return {
                id: imdbId,
                url: (d.url || ('https://www.imdb.com/title/' + imdbId + '/')),
                rating: d.rating || d.imdbRating || (d.ratings && d.ratings.rating) || '',
                votes: d.votes || d.numVotes || (d.ratings && d.ratings.votes) || '',
                year: d.year || d.releaseYear || '',
                runtime: d.runtime || d.runtimeMinutes || '',
                genres: Array.isArray(d.genres) ? d.genres.join(', ') : (d.genres || ''),
                directors: Array.isArray(d.directors) ? d.directors.join(', ') : (d.directors || ''),
                cast: Array.isArray(d.cast) ? d.cast.slice(0,6).join(', ') : (d.cast || ''),
                plot: d.plot || d.plotSummary || d.description || ''
            };
        } catch(e) {
            console.warn('OGFlix IMDb metadata unavailable:', e);
            return null;
        }
    }

    async function fetchWatchProviders(tmdbId, mediaType) {
        if (!tmdbId) return null;
        try {
            const type = mediaType === 'tv' ? 'tv' : 'movie';
            const res = await fetch(
                `${TMDB_BASE}/${type}/${tmdbId}/watch/providers?api_key=${API_KEY}`
            );
            if (!res.ok) return null;
            const data = await res.json();
            return data && data.results ? data.results.US || null : null;
        } catch(e) {
            return null;
        }
    }

    function escapeHtml(value) {
        return String(value || '').replace(/[&<>"']/g, function(ch) {
            return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch];
        });
    }

    /* OGFLIX SHARING SYSTEM — large icon buttons + popup windows */
    function ogflixShareMarkup(c){
        if (!document.getElementById('app-player')) return '';
        const t=c.title||document.title||'OGFlix', u=c.url||location.href;
        const btn=function(network,icon,label,cls){return '<button type=\"button\" class=\"ogflix-share-btn '+cls+'\" data-share-network=\"'+network+'\" aria-label=\"'+escapeHtml(label)+'\" title=\"'+escapeHtml(label)+'\"><i class=\"'+icon+'\"></i><span>'+escapeHtml(label)+'</span></button>';};
        return '<section class=\"ogflix-share\" data-ogflix-share data-share-title=\"'+escapeHtml(t)+'\" data-share-url=\"'+escapeHtml(u)+'\">'+
        '<div class=\"ogflix-share-head\"><div class=\"ogflix-share-title\"><i class=\"bx bx-share-alt\"></i><span style="font-size:20px;">Share With Your Friends</span></div><div class=\"ogflix-share-subtitle\">Share OGFlix everywhere</div></div>'+
        '<div class=\"ogflix-share-buttons\">'+
        btn('facebook','bx bxl-facebook','Facebook','facebook')+
        btn('x','bx bxl-twitter','X','x')+
        btn('whatsapp','bx bxl-whatsapp','WhatsApp','whatsapp')+
        btn('telegram','bx bxl-telegram','Telegram','telegram')+
        btn('reddit','bx bxl-reddit','Reddit','reddit')+
        btn('linkedin','bx bxl-linkedin','LinkedIn','linkedin')+
        btn('pinterest','bx bxl-pinterest','Pinterest','pinterest')+
        btn('threads','bx bx-at','Threads','threads')+
        btn('bluesky','bx bx-cloud','Bluesky','bluesky')+
        btn('tumblr','bx bxl-tumblr','Tumblr','tumblr')+
        btn('vk','bx bxl-vk','VK','vk')+
        btn('line','bx bx-message-rounded','LINE','line')+
        btn('instagram','bx bxl-instagram','Instagram','instagram')+
        btn('tiktok','bx bxl-tiktok','TikTok','tiktok')+
        btn('email','bx bx-envelope','Email','email')+
        btn('sms','bx bx-message-dots','SMS','sms')+
        btn('copy','bx bx-link','Copy Link','copy')+
        btn('native','bx bx-dots-horizontal-rounded','More','native')+
        '</div><div class=\"ogflix-share-status\" aria-live=\"polite\"></div></section>';
    }
    function ogflixOpenShareWindow(u){window.open(u,'ogflixShareWindow','width=760,height=700,resizable=yes,scrollbars=yes,noopener,noreferrer');}
    async function ogflixCopyText(value){
        try{if(navigator.clipboard){await navigator.clipboard.writeText(value);return true;}}catch(e){}
        try{const i=document.createElement('textarea');i.value=value;i.style.position='fixed';i.style.opacity='0';document.body.appendChild(i);i.focus();i.select();const ok=document.execCommand('copy');i.remove();return ok;}catch(e){return false;}
    }
    async function ogflixHandleShare(b){
        const w=b.closest('[data-ogflix-share]');if(!w)return;
        const t=w.getAttribute('data-share-title')||document.title,u=w.getAttribute('data-share-url')||location.href,n=b.getAttribute('data-share-network'),s=w.querySelector('.ogflix-share-status');
        const encU=encodeURIComponent(u), encT=encodeURIComponent(t), text=t+' '+u;
        if(n==='facebook') ogflixOpenShareWindow('https://www.facebook.com/sharer/sharer.php?u='+encU);
        else if(n==='x') ogflixOpenShareWindow('https://twitter.com/intent/tweet?text='+encT+'&url='+encU);
        else if(n==='whatsapp') ogflixOpenShareWindow('https://api.whatsapp.com/send?text='+encodeURIComponent(text));
        else if(n==='telegram') ogflixOpenShareWindow('https://t.me/share/url?url='+encU+'&text='+encT);
        else if(n==='reddit') ogflixOpenShareWindow('https://www.reddit.com/submit?url='+encU+'&title='+encT);
        else if(n==='linkedin') ogflixOpenShareWindow('https://www.linkedin.com/sharing/share-offsite/?url='+encU);
        else if(n==='pinterest') ogflixOpenShareWindow('https://www.pinterest.com/pin/create/button/?url='+encU+'&description='+encT);
        else if(n==='threads') ogflixOpenShareWindow('https://www.threads.net/intent/post?text='+encodeURIComponent(text));
        else if(n==='bluesky') { const copied=await ogflixCopyText(text); ogflixOpenShareWindow('https://bsky.app/'); if(s)s.textContent=copied?'Text + link copied. Paste it into Bluesky.':'Open Bluesky and paste the OGFlix link.'; }
        else if(n==='tumblr') ogflixOpenShareWindow('https://www.tumblr.com/widgets/share/tool?posttype=link&title='+encT+'&canonicalUrl='+encU);
        else if(n==='vk') ogflixOpenShareWindow('https://vk.com/share.php?url='+encU+'&title='+encT);
        else if(n==='line') ogflixOpenShareWindow('https://social-plugins.line.me/lineit/share?url='+encU+'&text='+encT);
        else if(n==='instagram' || n==='tiktok') { const copied=await ogflixCopyText(text); ogflixOpenShareWindow(n==='instagram'?'https://www.instagram.com/':'https://www.tiktok.com/'); if(s)s.textContent=copied?'Text + link copied. Paste it into '+(n==='instagram'?'Instagram.':'TikTok.'):('Open '+(n==='instagram'?'Instagram.':'TikTok.')+' and share the link.'); }
        else if(n==='email') window.location.href='mailto:?subject='+encT+'&body='+encodeURIComponent(text);
        else if(n==='sms') window.location.href='sms:?&body='+encodeURIComponent(text);
        else if(n==='copy') { const copied=await ogflixCopyText(u); if(s)s.textContent=copied?'Link copied to your clipboard.':'Copy failed — please copy the URL manually.'; }
        else if(n==='native') { if(navigator.share){try{await navigator.share({title:t,text:t,url:u});}catch(e){} } else { const copied=await ogflixCopyText(text); if(s)s.textContent=copied?'Text + link copied. Choose an app to paste it.':'Choose a social network above.'; } }
        if(s && ['facebook','x','whatsapp','telegram','reddit','linkedin','pinterest','threads','tumblr','vk','line'].indexOf(n)>=0) {s.textContent='Share window opened.';}
        if(s) setTimeout(()=>{s.textContent=''},3500);
    }
    function initOgflixShareEvents(){
        if(window.__ogflixShareEvents)return;window.__ogflixShareEvents=true;
        document.addEventListener('click',e=>{const b=e.target.closest('[data-share-network]');if(b)ogflixHandleShare(b)})
    }
    function initOgflixPostPageShare(){
        /* Share is rendered directly above You May Like This in the player markup. */
        return;
    }
    function initOgflixHomepageShare(){ return; }
    function initOgflixSharing(){
        initOgflixShareEvents();
    }


    /* Start social widgets only after OGFlix's player/select controls have
       completed their initialization. The sharing system is isolated from
       all SELECT/OPTION elements. */
    window.addEventListener('load', function(){
        window.setTimeout(function(){
            try {
                if (typeof initOgflixSharing === 'function') {
                    initOgflixSharing();
                }
            } catch(e) {}
        }, 1200);
    });

async function loadYouMayLike(currentPostUrl) {
    const container = document.getElementById('you-may-like-container');
    const labelsBox = document.getElementById('related-post-labels');
    if (!container) return;

    try {
        let labels = [];
        if (labelsBox) {
            labels = Array.from(labelsBox.querySelectorAll('.related-post-label'))
                .map(function(el) { return el.innerText.trim(); })
                .filter(Boolean);
        }

        /* Prefer the first useful post label for related content. */
        const ignoredLabels = ['Movies', 'TV', 'Music', 'MusicVideos', 'MusicAlbums', 'Games'];
        const usefulLabel = labels.find(function(label) {
            return ignoredLabels.indexOf(label) === -1;
        }) || labels[0] || '';

        let feedUrl = usefulLabel
            ? '/feeds/posts/default/-/' + encodeURIComponent(usefulLabel) + '?alt=json&max-results=50'
            : '/feeds/posts/default?alt=json&max-results=50';

        const response = await fetch(feedUrl);
        if (!response.ok) return;
        const data = await response.json();

        if (!data.feed || !data.feed.entry) {
            container.remove();
            return;
        }

        const currentUrl = String(currentPostUrl || window.location.href).split('#')[0];
        let posts = data.feed.entry.filter(function(post) {
            const linkObj = post.link && post.link.find(function(link) {
                return link.rel === 'alternate';
            });
            if (!linkObj) return false;
            return linkObj.href.split('#')[0] !== currentUrl;
        });

        if (!posts.length) {
            container.remove();
            return;
        }

        /* Shuffle the posts array randomly */
        for (let i = posts.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            const temp = posts[i];
            posts[i] = posts[j];
            posts[j] = temp;
        }

        /* Take up to 6 random posts */
        posts = posts.slice(0, 6);

        const grid = container.querySelector('.you-may-like-grid');
        if (!grid) return;

        grid.innerHTML = posts.map(function(post) {
            const linkObj = post.link.find(function(link) {
                return link.rel === 'alternate';
            });
            const title = post.title ? post.title.$t : 'Untitled';
            const content = post.content ? post.content.$t : '';
            let poster = getMatch(content, 'poster-url');

            if (!poster && post.media$thumbnail && post.media$thumbnail.url) {
                poster = post.media$thumbnail.url
                    .replace('/s72-c/', '/w342/')
                    .replace('/s72-c', '/w342');
            }

            if (!poster) {
                poster = 'https://via.placeholder.com/342x513/181818/777?text=OGFlix';
            }

            return '<a class="you-may-like-card" href="' + escapeHtml(linkObj.href) + '">' +
                '<img class="you-may-like-poster" src="' + escapeHtml(poster) + '" alt="' + escapeHtml(title) + '" loading="lazy">' +
                '<div class="you-may-like-info">' +
                    '<div class="you-may-like-name">' + escapeHtml(title) + '</div>' +
                    '<div class="you-may-like-meta">OGFlix</div>' +
                '</div>' +
            '</a>';
        }).join('');
    } catch (error) {
        console.error('You May Like This error:', error);
        container.remove();
    }
}


function ogflixCleanViewerText(value){
    return String(value || '')
        .replace(/4K\s*UHD\s*Dual\s*Audio/gi, '')
        .replace(/\s{2,}/g, ' ')
        .trim();
}
function ogflixCleanPostDom(root){
    if(!root) return;
    var walker=document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
    var nodes=[];
    while(walker.nextNode()) nodes.push(walker.currentNode);
    nodes.forEach(function(n){
        n.nodeValue=n.nodeValue.replace(/4K\s*UHD\s*Dual\s*Audio/gi,'');
    });
}

    async function initPlayer() {
        const raw = document.getElementById('post-body-raw');
        ogflixCleanPostDom(raw);
        const app = document.getElementById('app-player');
        if (!raw || !app) return;

        const getData = function(cls) {
            const el = raw.querySelector('.' + cls);
            return el ? el.innerText.trim() : '';
        };

        /* Collect every usable YouTube source in the post. */
        const youtubeSources = [];
        const addYouTube = function(url, name) {
            const id = getYouTubeId(url);
            if (!id) return;
            if (!youtubeSources.some(function(x){ return x.id === id; })) {
                youtubeSources.push({ id:id, url:url, name:(name || 'YouTube').trim() });
            }
        };

        raw.querySelectorAll('iframe, a, button, video, source').forEach(function(el) {
            const src = el.getAttribute('src') || el.getAttribute('href') ||
                        el.getAttribute('data-url') || el.getAttribute('data-src') || '';
            const onclick = el.getAttribute('onclick') || '';
            addYouTube(src, el.innerText || el.getAttribute('title') || 'YouTube');
            (onclick.match(/https?:[^'"\s)]+/g) || []).forEach(function(url) {
                addYouTube(url, el.innerText || 'YouTube');
            });
        });

        const pastedUrls = (raw.innerHTML || '').match(/https?:\/\/(?:www\.|m\.|music\.)?(?:youtube\.com\/(?:watch\?v=|embed\/|shorts\/|live\/)|youtu\.be\/)[^"'<\s]+/gi) || [];
        pastedUrls.forEach(function(url){ addYouTube(url, 'YouTube'); });

        /* Collect Mixcloud iframe/widget embeds exactly as supplied by Mixcloud.
           These are kept as external players rather than converted to another
           player format. This works for shows, tracks and playlists. */
        const mixcloudSources = [];
        const addMixcloud = function(url, name, title){
            if (!url || !/mixcloud\.com/i.test(url)) return;
            const clean = String(url).trim();
            if (!clean || mixcloudSources.some(function(x){ return x.url === clean; })) return;
            mixcloudSources.push({url:clean, name:(name || 'Mixcloud').trim(), title:(title || name || 'Mixcloud Player').trim()});
        };
        raw.querySelectorAll('iframe[src*="mixcloud.com"], iframe[src*="player-widget.mixcloud.com"], a[href*="mixcloud.com"]').forEach(function(el){
            addMixcloud(el.getAttribute('src') || el.getAttribute('href') || '', el.innerText || el.getAttribute('title') || 'Mixcloud', el.getAttribute('title') || el.innerText || 'Mixcloud Player');
        });
        const pastedMixcloudUrls = (raw.innerHTML || '').match(/https?:\/\/[^"\'<\s]*mixcloud\.com[^"\'<\s]*/gi) || [];
        pastedMixcloudUrls.forEach(function(url){ addMixcloud(url, 'Mixcloud', 'Mixcloud Player'); });

        /* Build a clean, readable description.  The old version used nearly all
           remaining post text, which could make the Description area look like
           a dump of labels, links and platform information.  Prefer Blogger's
           actual meta description, then explicit description fields, then a
           cleaned excerpt from the post body. */
        const bloggerMetaDescription = (document.querySelector('meta[name="description"]') || {}).content || '';
        const explicitDescription =
            getData('description') ||
            getData('video-description') ||
            getData('song-description') ||
            getData('data-desc');

        let bodyDescription = '';
        const bodyClone = raw.cloneNode(true);
        bodyClone.querySelectorAll('script,style,iframe,video,a,button,form,img,.poster-url,.cover-url,.data-title,.data-meta,.data-desc,.description,.video-description,.song-description,.data-stream,.data-dl,.streaming-platform').forEach(function(el){ el.remove(); });
        bodyDescription = (bodyClone.innerText || '').replace(/\s+/g,' ').trim();

        function cleanDescription(value) {
            return String(value || '')
                .replace(/https?:\/\/\S+/gi, '')
                .replace(/(?:Apple Music|Spotify|Tidal|Pandora|iHeartRadio|Amazon Music|Amazon|Deezer)\s*:?/gi, '')
                .replace(/\s+/g, ' ')
                .replace(/^Description\s*:?\s*/i, '')
                .trim();
        }

        const cleanMetaDescription = cleanDescription(bloggerMetaDescription)
            .replace(/4K\s*UHD\s*Dual\s*Audio/gi, '');
        const cleanExplicitDescription = cleanDescription(explicitDescription)
            .replace(/4K\s*UHD\s*Dual\s*Audio/gi, '');
        const cleanBodyDescription = cleanDescription(bodyDescription)
            .replace(/4K\s*UHD\s*Dual\s*Audio/gi, '');

        /* Prefer a real YouTube thumbnail as the cover/social image when a YouTube
           video is present. This is also the default Open Graph/Twitter image. */
        const youtubeThumb = youtubeSources.length
            ? 'https://i.ytimg.com/vi/' + encodeURIComponent(youtubeSources[0].id) + '/maxresdefault.jpg'
            : '';

        const basicData = {
            title: getData('data-title') || (raw.querySelector('h1,h2,h3') ? raw.querySelector('h1,h2,h3').innerText.trim() : document.title),
            desc: cleanMetaDescription || cleanExplicitDescription || cleanBodyDescription || '',
            meta: getData('data-meta').replace(/4K\s*UHD\s*Dual\s*Audio/gi, '').replace(/\s{2,}/g, ' ').trim(),
            poster: getData('poster-url') || getData('cover-url') || youtubeThumb,
            seasons: Array.from(raw.querySelectorAll('.data-season')),
            servers: Array.from(raw.querySelectorAll('.data-stream')),
            downloads: Array.from(raw.querySelectorAll('.data-dl')),
            youtube: youtubeSources,
            mixcloud: mixcloudSources
        };

        let meta = Object.assign({}, basicData);
        const imdbId = getImdbIdFromContent(raw.innerHTML || '');
        if (imdbId) {
            meta.imdb = await fetchIMDbMetadata(imdbId);
            meta.imdbId = imdbId;
        }

        /* Music Video titles use: Artist - Song Title */
        const musicVideoTitle = parseMusicVideoTitle(meta.title);
        meta.artist = musicVideoTitle.artist;
        meta.songTitle = musicVideoTitle.song;

        /* YouTube oEmbed supplies the real video title/author. It does not expose
           the full YouTube description, so the Blogger post remains the description source. */
        if (meta.youtube.length) {
            const ytMeta = await fetchYouTubeMetadata(meta.youtube[0].id);
            if (ytMeta) {
                /* Keep the Blogger title format "Artist - Song Title"
                   as the canonical OGFlix title. Use YouTube metadata for
                   author/thumbnail enrichment only. */
                meta.author = ytMeta.author_name || '';
                if (!meta.poster) meta.poster = ytMeta.thumbnail_url || youtubeThumb;
                if (!meta.meta && meta.author) meta.meta = 'By ' + meta.author;
            }
        }

        /* Explicit Blogger cover image overrides only when there is no video thumbnail.
           This keeps the requested video thumbnail as the social/share image. */
        const explicitPoster = getData('poster-url') || getData('cover-url');
        if (explicitPoster && !meta.youtube.length) meta.poster = explicitPoster;

        let tmdb = await fetchTMDB(meta.title);
        if (tmdb) {
            meta.id = tmdb.id;
            meta.mediaType = tmdb.media_type || 'movie';
            if (!meta.desc) meta.desc = tmdb.overview || '';
            if (!meta.poster && tmdb.poster_path) meta.poster = IMG_W500 + tmdb.poster_path;
            if (!meta.meta) {
                meta.meta = [
                    tmdb.media_type === 'tv' ? 'TV' : 'Movie',
                    tmdb.release_date || tmdb.first_air_date || ''
                ].filter(Boolean).join(' • ');
            }
            meta.watchProviders = await fetchWatchProviders(tmdb.id, meta.mediaType);
            if (!meta.imdbId && tmdb.imdb_id) {
                meta.imdbId = tmdb.imdb_id;
                meta.imdb = await fetchIMDbMetadata(meta.imdbId);
            }
        }

        if (meta.imdb && meta.imdb.url) {
            const imdbBits = [];
            if (meta.imdb.rating) imdbBits.push('IMDb ' + meta.imdb.rating);
            if (meta.imdb.year) imdbBits.push(String(meta.imdb.year));
            if (meta.imdb.runtime) imdbBits.push(String(meta.imdb.runtime).match(/\d+/) ? String(meta.imdb.runtime).replace(/\s*minutes?/i,' min') : String(meta.imdb.runtime));
            if (imdbBits.length) meta.meta = [meta.meta, imdbBits.join(' • ')].filter(Boolean).join(' • ');
            if (!meta.desc && meta.imdb.plot) meta.desc = meta.imdb.plot;
        }

        if (!meta.poster) {
            const firstImg = raw.querySelector('img[src]');
            if (firstImg) meta.poster = firstImg.getAttribute('src');
        }

        if (!meta.desc) {
            meta.desc = 'Watch this media and explore all available streaming platforms below.';
        }


        /* Resolve the actual playable URL from Blogger stream elements.
           A .data-stream entry may be an anchor, button, span, or custom
           element. Do not rely on .href because buttons/spans have no href. */
        const getStreamUrl = function(node) {
            if (!node) return '';
            const attrs = ['href', 'src', 'data-url', 'data-src', 'data-href'];
            for (let i = 0; i < attrs.length; i++) {
                const value = node.getAttribute(attrs[i]);
                if (value && value.trim()) return value.trim();
            }

            const onclick = node.getAttribute('onclick') || '';
            const match = onclick.match(/(?:playUrl|window\.playUrl)\s*\(\s*['"]([^'"]+)['"]/i);
            if (match && match[1]) return match[1].trim();

            const htmlUrl = (node.innerHTML || '').match(/https?:\/\/[^"'<> \t\r\n]+/i);
            return htmlUrl ? htmlUrl[0].trim() : '';
        };

        const platformItems = [];
        const addPlatform = function(label, url, icon, cls) {
            if (!url) return;
            const clean = url.trim();
            if (!clean || platformItems.some(function(x){ return x.label === label || x.url === clean; })) return;
            platformItems.push({label:label, url:clean, icon:icon || 'bx bx-link', cls:cls || ''});
        };

        meta.youtube.forEach(function(item){ addPlatform('YouTube', item.url, 'bx bxl-youtube', 'youtube'); });
        meta.servers.forEach(function(node){
            const streamUrl = getStreamUrl(node);
            if (streamUrl) {
                addPlatform(
                    (node.innerText || node.getAttribute('title') || 'Streaming').trim(),
                    streamUrl,
                    'bx bx-play-circle',
                    'direct-service'
                );
            }
        });

        /* Accept platform links supplied directly in the Blogger post. */
        raw.querySelectorAll('a.streaming-platform, a[data-platform]').forEach(function(node){
            addPlatform(node.getAttribute('data-platform') || node.innerText || 'Streaming', node.href, 'bx bx-link', '');
        });

        /* For music videos, resolve the actual song across streaming
           services using the post's real YouTube URL. If a service cannot
           be resolved, retain a useful service search as a fallback. */
        let songLinks = null;
        if (meta.youtube.length) {
            songLinks = await fetchSongLinks(meta.youtube[0].url);
        }

        /* album.link is the universal smart-link resource for the song.
           It presents the matching release and the available streaming
           platforms from one canonical page. */
        if (songLinks && songLinks.ogflixAlbumLink) {
            addPlatform(
                'All Streaming Services',
                songLinks.ogflixAlbumLink,
                'bx bx-link-external',
                'music-service album-link-service direct-service'
            );
        }

        const serviceDefs = [
            ['Apple Music', 'appleMusic', 'https://music.apple.com/us/search?term=', 'bx bxl-apple'],
            ['Spotify', 'spotify', 'https://open.spotify.com/search/', 'bx bxl-spotify'],
            ['Tidal', 'tidal', 'https://tidal.com/search?q=', 'bx bx-waveform'],
            ['Pandora', 'pandora', 'https://www.pandora.com/search/', 'bx bx-radio'],
            ['Amazon Music', 'amazonMusic', 'https://music.amazon.com/search/', 'bx bxl-amazon'],
            ['Deezer', 'deezer', 'https://www.deezer.com/search/', 'bx bx-music']
        ];

        const serviceQuery = encodeURIComponent(
            [meta.artist, meta.songTitle || meta.title].filter(Boolean).join(' ')
        );

        serviceDefs.forEach(function(def) {
            const label = def[0];
            const key = def[1];
            const resolved = songLinks && songLinks.linksByPlatform[key]
                ? songLinks.linksByPlatform[key].url
                : '';
            const fallback = def[2] + serviceQuery;
            addPlatform(label, resolved || fallback, def[3], resolved ? 'music-service direct-service' : 'music-service');
        });

        /* If Songlink returned an exact smart-link URL, album.link is
           available above. Keep this fallback for source URLs that are
           already album.link links. */
        if (!songLinks && meta.youtube.length && /album\.link/i.test(meta.youtube[0].url)) {
            addPlatform(
                'Album.link',
                meta.youtube[0].url,
                'bx bx-album',
                'music-service album-link-service direct-service'
            );
        }

        /* YouTube Music may be returned by Odesli even when the regular
           YouTube URL is the source. */
        if (songLinks && songLinks.linksByPlatform && songLinks.linksByPlatform.youtubeMusic) {
            addPlatform(
                'YouTube Music',
                songLinks.linksByPlatform.youtubeMusic.url,
                'bx bxl-youtube',
                'music-service direct-service'
            );
        }

        /* Add a movie/TV watch guide when TMDB has provider information.
           Provider names are shown as destinations, while the TMDB watch
           link handles the actual regional availability. */
        if (meta.watchProviders && meta.watchProviders.link) {
            const providerGroups = []
                .concat(meta.watchProviders.flatrate || [])
                .concat(meta.watchProviders.free || [])
                .concat(meta.watchProviders.ads || [])
                .concat(meta.watchProviders.rent || [])
                .concat(meta.watchProviders.buy || []);

            const names = [];
            providerGroups.forEach(function(p) {
                if (p && p.provider_name && names.indexOf(p.provider_name) === -1) {
                    names.push(p.provider_name);
                }
            });

            addPlatform(
                names.length ? 'Where To Watch • ' + names.slice(0, 4).join(', ') : 'Where To Watch',
                meta.watchProviders.link,
                'bx bx-tv',
                'movie-service'
            );
        }

        const existingByLabel = {};
        platformItems.forEach(function(p){ existingByLabel[p.label.toLowerCase()] = p; });
        serviceDefs.forEach(function(def){
            const key = def[0].toLowerCase();
            if (!existingByLabel[key]) {
                addPlatform(def[0], def[1], def[2], 'music-service');
            } else {
                existingByLabel[key].icon = def[2];
                existingByLabel[key].cls = 'music-service';
            }
        });

        const platformButtons = platformItems.map(function(p){
            return '<a class="platform-btn ' + p.cls + '" href="' + escapeHtml(p.url) + '" target="_blank" rel="noopener noreferrer"><i class="' + p.icon + '"></i>' + escapeHtml(p.label) + '</a>';
        }).join('');

        const sourceButtons = meta.youtube.map(function(item) {
            const youtubeUrl = item.url || '';
            if (!youtubeUrl) return '';
            return '<button type="button" class="platform-btn youtube" data-url="' +
                escapeHtml(youtubeUrl) +
                '" onclick="playUrl(this.dataset.url)" title="Play this video"><i class="bx bxl-youtube"></i>' +
                escapeHtml(item.name || 'YouTube') + '</button>';
        }).join('') + meta.mixcloud.map(function(item) {
            return '<button type="button" class="platform-btn mixcloud" data-url="' +
                escapeHtml(item.url) +
                '" onclick="playUrl(this.dataset.url)" title="Play Mixcloud player"><i class="bx bx-podcast"></i>' +
                escapeHtml(item.name || 'Mixcloud') + '</button>';
        }).join('') + meta.servers.map(function(node) {
            const href = getStreamUrl(node);
            if (!href) return '';
            return '<button type="button" class="platform-btn" data-url="' +
                escapeHtml(href) +
                '" onclick="playUrl(this.dataset.url)"><i class="bx bx-play"></i>' +
                escapeHtml((node.innerText || node.getAttribute('title') || 'Streaming').trim()) + '</button>';
        }).join('');

        app.innerHTML =
            '<div class="modal-overlay active">' +
                '<i class="bx bx-left-arrow-alt back-btn" onclick="window.history.back()"></i>' +
                '<div class="player-responsive" id="player-shell">' +
                    '<iframe id="main-player" src="about:blank" frameborder="0" allow="autoplay; accelerometer; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen="allowfullscreen" referrerpolicy="strict-origin-when-cross-origin"></iframe>' +
                    '<video id="main-video" playsinline webkit-playsinline controls autoplay preload="auto" style="display:none;position:absolute;inset:0;width:100%;height:100%;background:#000;"></video>' +
                '</div>' +
                '<div class="modal-info">' +
                    '<div class="media-description">' +
                        '<div class="description-label">Description</div>' +
                        '<h1 class="text-4xl font-bold mb-3 text-white">' + escapeHtml(meta.title) + '</h1>' +
                        '<div class="flex gap-4 text-gray-400 font-bold mb-6 text-sm flex-wrap">' +
                            (meta.youtube.length ? '<span class="text-red-500"><i class="bx bxl-youtube"></i> YouTube</span>' : (meta.mixcloud.length ? '<span class="text-orange-400"><i class="bx bx-podcast"></i> Mixcloud</span>' : '<span class="text-green-500">Available Now</span>')) +
                            (meta.meta ? '<span>' + escapeHtml(meta.meta) + '</span>' : '') +
                            (meta.author ? '<span>By ' + escapeHtml(meta.author) + '</span>' : '') +
                            '<span class="border border-gray-500 px-1 text-xs rounded text-white">HD</span>' +
                            (meta.imdb && meta.imdb.url ? '<a class="border border-yellow-500/60 px-2 py-1 text-xs rounded text-yellow-300 hover:bg-yellow-500/10" href="' + escapeHtml(meta.imdb.url) + '" target="_blank" rel="noopener noreferrer"><i class="bx bx-star"></i> IMDb' + (meta.imdb.rating ? ' ' + escapeHtml(meta.imdb.rating) : '') + '</a>' : '') +
                        '</div>' +
                        '<p class="text-white leading-relaxed text-lg">' + escapeHtml(meta.desc) + '</p>' +
                        '<div class="platform-section">' +
                            '<div class="platform-label"></div>' +
                            '<div class="platform-grid">' + platformButtons + '</div>' +
                            '<div class="platform-note"></div>' +
                        '</div>' +
                        (meta.downloads.length ? '<div class="dl-movie-row">' + meta.downloads.map(function(l){ return '<a href="' + escapeHtml(l.href) + '" target="_blank" rel="noopener noreferrer" class="dl-btn"><i class="bx bxs-download"></i> ' + escapeHtml(l.innerText || 'Download') + '</a>'; }).join('') + '</div>' : '') +
                    '</div>' +
                    '<div class="cover-wrap">' +
                        (meta.poster ? '<img class="cover-image" src="' + escapeHtml(meta.poster) + '" alt="' + escapeHtml(meta.title) + ' cover">' : '<div class="cover-image flex items-center justify-center bg-gray-900 text-gray-600">No Cover</div>') +
                        '' +
                    '</div>' +
                '</div>' +
                '<div class="px-[4%] pb-12 max-w-[1500px] mx-auto">' +
                    '<div class="flex flex-wrap gap-3">' +
                        (sourceButtons || '<span class="text-gray-500">No additional playable source was found in this post.</span>') +
                    '</div>' +
                '</div>' +
                ogflixShareMarkup({title:meta.title,url:window.location.href}) +
                '<div id="you-may-like-container" class="you-may-like">' +
                    '<h3 class="you-may-like-title">You May Like This</h3>' +
                    '<div class="you-may-like-grid"></div>' +
                '</div>' +
            '</div>';

        ogflixCleanPostDom(app);

        updateSocialMeta(meta);
        document.title = meta.title + ' | ' + (document.title || 'OGFlix');
        loadYouMayLike(window.location.href);

        if (meta.youtube.length) {
            playUrl(meta.youtube[0].url);
        } else if (meta.mixcloud.length) {
            playUrl(meta.mixcloud[0].url);
        } else if (meta.seasons.length > 0 && meta.id) {
            /* Preserve existing episode behavior. */
            const seasonTabs = document.createElement('div');
            seasonTabs.id = 'season-tabs';
            const epList = document.createElement('div');
            epList.id = 'ep-list';
            epList.className = 'ep-container mt-6';
            const sourceArea = document.querySelector('.px-\\[4\\%\\].pb-12');
            if (sourceArea) {
                sourceArea.innerHTML = '';
                sourceArea.appendChild(seasonTabs);
                sourceArea.appendChild(epList);
            }
            loadSeasons(meta.id, meta.seasons);
        } else if (meta.servers.length) {
            const firstStreamUrl = getStreamUrl(meta.servers[0]);
            if (firstStreamUrl) playUrl(firstStreamUrl);
        }
    }

    function setMeta(property, content) {
        if (!content) return;
        let el = document.querySelector('meta[property="' + property + '"]');
        if (!el) {
            el = document.createElement('meta');
            el.setAttribute('property', property);
            document.head.appendChild(el);
        }
        el.setAttribute('content', content);
    }
    function setNameMeta(name, content) {
        if (!content) return;
        let el = document.querySelector('meta[name="' + name + '"]');
        if (!el) {
            el = document.createElement('meta');
            el.setAttribute('name', name);
            document.head.appendChild(el);
        }
        el.setAttribute('content', content);
    }
    function updateSocialMeta(meta) {
        setMeta('og:title', meta.title);
        setMeta('og:description', meta.desc);
        setMeta('og:type', 'video.other');
        setMeta('og:url', window.location.href);
        if (meta.poster) {
            setMeta('og:image', meta.poster);
            setMeta('og:image:secure_url', meta.poster);
            setNameMeta('twitter:image', meta.poster);
        }
        setNameMeta('description', meta.desc);
        setNameMeta('twitter:title', meta.title);
        setNameMeta('twitter:description', meta.desc);
    }

    async function loadSeasons(tmdbId, seasonNodes) {
        const tabs = document.getElementById('season-tabs');
        seasonNodes.forEach((node, i) => {
            const sNum = i+1;
            const btn = document.createElement('div');
            btn.className = `tab-btn ${i===0 ? 'active' : ''}`;
            btn.innerText = `Season ${sNum}`;
            btn.onclick = () => loadSeasonData(tmdbId, sNum, node, btn);
            tabs.appendChild(btn);
        });
        loadSeasonData(tmdbId, 1, seasonNodes[0], tabs.children[0]);
    }

    async function loadSeasonData(tmdbId, sNum, node, btn) {
        document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        const list = document.getElementById('ep-list');
        list.innerHTML = 'Loading...';

        const seasonData = await fetch(`${TMDB_BASE}/tv/${tmdbId}/season/${sNum}?api_key=${API_KEY}`).then(r=>r.json());
        const temp = document.createElement('div');
        temp.innerHTML = node.innerHTML;
        const streams = Array.from(temp.querySelectorAll('button'));
        const downloads = Array.from(temp.querySelectorAll('a'));

        let html = '';
        streams.forEach((el, idx) => {
            const onclick = el.getAttribute('onclick') || '';
            const url = onclick.match(/(?:playUrl|window\.playUrl)\s*\(\s*['"]([^'"]+)['"]/i)?.[1];
            if(!url) return;
            const ep = seasonData.episodes ? seasonData.episodes[idx] : null;
            const title = ep ? ep.name : el.innerText;
            const desc = ep ? ep.overview : '';
            const img = ep && ep.still_path ? IMG_W500 + ep.still_path : 'https://via.placeholder.com/160x90?text=No+Img';
            const num = idx+1;
            const dlLink = downloads[idx] ? downloads[idx].href : null;

            html += `<div class="ep-row"><div class="flex items-center gap-3 flex-1 cursor-pointer" onclick="playUrl('${url}')"><span class="ep-idx">${num}</span><div class="ep-thumb-wrap"><img src="${img}" class="ep-thumb" loading="lazy"/><div class="ep-play-icon"><i class='bx bx-play text-3xl text-white'></i></div></div><div class="ep-meta"><div class="ep-title">${title}</div><div class="ep-desc">${desc}</div></div></div>${dlLink ? `<a href="${dlLink}" target="_blank" class="dl-icon-btn"><i class='bx bxs-download'></i></a>` : ''}</div>`;
        });
        list.innerHTML = html;
        if(streams.length > 0) {
            const firstOnclick = streams[0].getAttribute('onclick') || '';
            const firstUrl = firstOnclick.match(/(?:playUrl|window\.playUrl)\s*\(\s*['"]([^'"]+)['"]/i)?.[1];
            if(firstUrl) playUrl(firstUrl);
        }
    }

    async function fetchTMDB(query) {
        try {
            const clean = query.replace(/\(\d{4}\)/, '').trim();
            const res = await fetch(`${TMDB_BASE}/search/multi?api_key=${API_KEY}&query=${encodeURIComponent(clean)}`);
            const data = await res.json();
            return data.results[0];
        } catch(e) { return null; }
    }

    function isMixcloudUrl(url) {
        return /(^|\.)mixcloud\.com(\/|:)/i.test(String(url || ''));
    }

    /* Enable Mixcloud widgets everywhere: posts, static pages, homepage
       widgets and dynamically inserted content. The embed code remains
       visible and unrestricted, as required by Mixcloud's widget policy. */
    function ogflixEnableMixcloudEmbeds(root) {
        var scope = root || document;
        if (!scope.querySelectorAll) return;
        var frames = scope.querySelectorAll('iframe[src*="mixcloud.com"], iframe[src*="player-widget.mixcloud.com"]');
        Array.prototype.forEach.call(frames, function(frame){
            if (!frame || !frame.getAttribute('src')) return;
            frame.classList.add('ogflix-mixcloud-embed');
            frame.setAttribute('allow','autoplay; encrypted-media; fullscreen; picture-in-picture');
            frame.setAttribute('allowfullscreen','allowfullscreen');
            frame.setAttribute('loading', frame.getAttribute('loading') || 'lazy');
            frame.setAttribute('referrerpolicy','strict-origin-when-cross-origin');
            frame.setAttribute('scrolling','no');
            frame.style.display='block';
            frame.style.width='100%';
            frame.style.maxWidth='100%';
            frame.style.minWidth='0';
            if (!frame.getAttribute('height')) frame.setAttribute('height','180');

            /* Keep every official Mixcloud widget visible and unrestricted.
               Do not hide, replace, scrape, or proxy the Mixcloud player. */
            var parent = frame.parentElement;
            if (parent && parent.tagName === 'A' && /mixcloud\.com/i.test(parent.href || '')) return;
            if (!parent || !parent.classList.contains('ogflix-mixcloud-wrap')) {
                var wrap = document.createElement('div');
                wrap.className='ogflix-mixcloud-wrap';
                frame.parentNode.insertBefore(wrap, frame);
                wrap.appendChild(frame);
            }
        });
    }
    window.ogflixEnableMixcloudEmbeds = ogflixEnableMixcloudEmbeds;
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', function(){ ogflixEnableMixcloudEmbeds(document); });
    } else {
        ogflixEnableMixcloudEmbeds(document);
    }
    try {
        new MutationObserver(function(mutations){
            mutations.forEach(function(m){
                Array.prototype.forEach.call(m.addedNodes || [], function(node){
                    if (node && node.nodeType === 1) ogflixEnableMixcloudEmbeds(node);
                });
            });
        }).observe(document.documentElement,{childList:true,subtree:true});
    } catch(e) {}

    window.playUrl = function(url) {
        var iframe = document.getElementById('main-player');
        var video = document.getElementById('main-video');
        if ((!iframe && !video) || !url) return;

        // Always reset both players so switching sources does not leave
        // another video playing in the background.
        if (iframe) iframe.src = 'about:blank';
        if (video) {
            video.pause();
            video.removeAttribute('src');
            video.load();
        }

        if (isYouTubeUrl(url)) {
            if (iframe) {
                iframe.style.display = 'block';
                if (video) video.style.display = 'none';
                iframe.src = youtubeEmbedUrl(url);
            }
        } else if (isMixcloudUrl(url)) {
            if (iframe) {
                iframe.style.display = 'block';
                if (video) video.style.display = 'none';
                iframe.setAttribute('allow','autoplay; encrypted-media; fullscreen; picture-in-picture');
                iframe.setAttribute('allowfullscreen','allowfullscreen');
                iframe.src = url;
            }
        } else if (isDirectVideoUrl(url)) {
            if (iframe) iframe.style.display = 'none';
            if (video) {
                video.style.display = 'block';
                video.src = url;
                video.muted = false;
                video.defaultMuted = false;
                video.autoplay = true;
                video.playsInline = true;
                var playPromise = video.play();
                if (playPromise && playPromise.catch) {
                    playPromise.catch(function(){
                        // Browsers may block audible autoplay. Keep the requested
                        // unmuted state and let the native controls provide play.
                        video.muted = false;
                    });
                }
            }
        } else {
            // Preserve support for hosted players/other embeds.
            if (iframe) {
                iframe.style.display = 'block';
                if (video) video.style.display = 'none';
                iframe.src = url;
            }
        }

        window.scrollTo({top:0, behavior:'smooth'});
    }
    function getMatch(content, cls) { const regex = new RegExp(`class=["']${cls}["'][^>]*>(.*?)<\/div>`); const match = content.match(regex); return match ? match[1] : ''; }
    //

/**/ var uri = window.location.toString();if (uri.indexOf("?m=1","?m=1") > 0) {var clean_uri = uri.substring(0, uri.indexOf("?m=1"));window.history.replaceState({}, document.title, clean_uri); }; /**/
    // Premium OGFlix channel selector
    (function(){
      var selector=document.getElementById('ogChannelSelector');
      var button=document.getElementById('ogChannelButton');
      var current=document.getElementById('ogChannelCurrent');
      if(!selector||!button)return;
      button.addEventListener('click',function(e){e.stopPropagation();var open=selector.classList.toggle('open');button.setAttribute('aria-expanded',open?'true':'false');});
      document.querySelectorAll('#ogChannelDropdown .og-channel-option').forEach(function(link){
        link.addEventListener('click',function(){current.textContent=this.getAttribute('data-channel')||this.textContent.trim();selector.classList.remove('open');button.setAttribute('aria-expanded','false');});
      });
      document.addEventListener('click',function(e){if(!selector.contains(e.target)){selector.classList.remove('open');button.setAttribute('aria-expanded','false');}});
      document.addEventListener('keydown',function(e){if(e.key==='Escape'){selector.classList.remove('open');button.setAttribute('aria-expanded','false');}});
    })();

(function(){
  function initOGFlixAutoplay(){
    if(!document.body) return;

    var isPost = document.body.classList.contains('item-view') ||
                 document.querySelector('body.item-view') ||
                 document.querySelector('.blog-posts .post.hentry');

    if(!isPost) return;

    // Native HTML5 videos.
    document.querySelectorAll('video').forEach(function(video){
      try{
        video.setAttribute('autoplay','autoplay');
        video.autoplay = true;
        video.setAttribute('playsinline','playsinline');
        video.playsInline = true;
        video.muted = true;
        video.setAttribute('muted','muted');
        var p = video.play();
        if(p && typeof p.catch === 'function'){ p.catch(function(){}); }
      }catch(e){}
    });

    // YouTube embeds.
    document.querySelectorAll('iframe[src*="youtube.com"], iframe[src*="youtube-nocookie.com"]').forEach(function(frame){
      try{
        var src = frame.getAttribute('src') || '';
        if(!src) return;
        var url = new URL(src, window.location.href);
        url.searchParams.set('autoplay','1');
        url.searchParams.set('mute','1');
        url.searchParams.set('playsinline','1');
        url.searchParams.set('enablejsapi','1');
        frame.setAttribute('allow','autoplay; encrypted-media; picture-in-picture; fullscreen');
        frame.setAttribute('allowfullscreen','allowfullscreen');
        frame.src = url.toString();
      }catch(e){}
    });

    // Generic embeds marked for autoplay.
    document.querySelectorAll('iframe[data-autoplay="true"], iframe[data-autoplay="1"]').forEach(function(frame){
      try{
        var src = frame.getAttribute('src') || '';
        if(!src) return;
        var url = new URL(src, window.location.href);
        url.searchParams.set('autoplay','1');
        frame.setAttribute('allow','autoplay; fullscreen; picture-in-picture');
        frame.src = url.toString();
      }catch(e){}
    });
  }

  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', initOGFlixAutoplay);
  }else{
    initOGFlixAutoplay();
  }

  window.addEventListener('pageshow', function(){
    setTimeout(initOGFlixAutoplay, 50);
  });
})();

(function(){
  function moveBossedUpBelowPopular(){
    var popular=document.getElementById('you-may-like-container');
    var bossed=document.getElementById('bossed-up-tv-section');
    if(!popular || !bossed) return;
    if(popular.nextElementSibling !== bossed){
      popular.parentNode.insertBefore(bossed,popular.nextSibling);
    }
  }
  if(document.readyState==='loading'){
    document.addEventListener('DOMContentLoaded',moveBossedUpBelowPopular);
  }else{
    moveBossedUpBelowPopular();
  }
  var observer=new MutationObserver(function(){ moveBossedUpBelowPopular(); });
  observer.observe(document.body,{childList:true,subtree:true});
  setTimeout(function(){ observer.disconnect(); },15000);
})();
